INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('summon-night-craft-sword-monogatari---hajimari-no-ishi-jcaravan', 'GAMEBOYADVANCE', 'Summon Night Craft Sword Monogatari - Hajimari no Ishi (J)(Caravan)', '2006', 'RPG', 'Flight-Plan', '1', 'Action RPG', 'Action-RPG with weapon crafting and dungeon crawling.', 'Discover the origin stone and protect the land.', 'The final epic entry in the Swordcraft Story trilogy.', 'Summon Night Craft Sword Monogatari: Hajimari no Ishi is the third game in the series. Experience the most refined crafting and combat mechanics of the franchise in this Japanese GBA gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-aladdin-ii-unl', 'GAMEBOYADVANCE', 'Super Aladdin II (Unl)', '2004', 'Platformer', 'Unlicensed', '1', 'Platform Action', '2D side-scrolling platformer (Unlicensed/Bootleg).', 'Guide Aladdin through levels based on the animated film.', 'A unique unlicensed take on the Aladdin story.', 'Super Aladdin II is an interesting bootleg title that features classic 16-bit style platforming. Navigate through Agrabah and defeat guards in this rare and curious GBA software.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-army-war-uvenom', 'GAMEBOYADVANCE', 'Super Army War (U)(Venom)', '2003', 'Strategy', 'LucasArts', '1', 'Real-Time Strategy', 'Side-scrolling strategy and combat simulation.', 'Command your units to capture the enemy base and win the war.', 'A unique 2D battlefield management game.', 'Super Army War (Glory Days) is an addictive mix of action and strategy. Control a helicopter or plane to provide air support while managing ground troops in this intense and tactical GBA war game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-black-bass-advance-elightforce', 'GAMEBOYADVANCE', 'Super Black Bass Advance (E)(Lightforce)', '2001', 'Sports', 'Starfish', '1', 'Fishing', 'Fishing simulation with realistic mechanics and locations.', 'Catch the biggest Black Bass to win the tournament.', 'The premier handheld bass fishing experience.', 'Super Black Bass Advance brings professional fishing to the GBA. Manage your lure, tension, and location to land prize-winning fish across various lakes in this detailed and relaxing simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-black-bass-advance-jeurasia', 'GAMEBOYADVANCE', 'Super Black Bass Advance (J)(Eurasia)', '2001', 'Sports', 'Starfish', '1', 'Fishing', 'Fishing simulation with realistic mechanics and locations.', 'Catch the biggest Black Bass to win the tournament.', 'The premier handheld bass fishing experience.', 'Super Black Bass Advance brings professional fishing to the GBA. Manage your lure, tension, and location to land prize-winning fish across various lakes in this detailed and relaxing simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bubble-pop-eindependent', 'GAMEBOYADVANCE', 'Super Bubble Pop (E)(Independent)', '2002', 'Puzzle', 'MumboJumbo', '1', 'Arcade Puzzle', '3D-style puzzle-shooter with rhythmic elements.', 'Pop bubbles to the beat and clear the grid.', 'Flashy and rhythmic bubble-popping puzzle game.', 'Super Bubble Pop features a unique perspective on the bubble-shooter genre. Align bubbles in 3D-style grids and enjoy a high-energy soundtrack in this colorful and stylish GBA puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bubble-pop-ueurasia', 'GAMEBOYADVANCE', 'Super Bubble Pop (U)(Eurasia)', '2002', 'Puzzle', 'MumboJumbo', '1', 'Arcade Puzzle', '3D-style puzzle-shooter with rhythmic elements.', 'Pop bubbles to the beat and clear the grid.', 'Flashy and rhythmic bubble-popping puzzle game.', 'Super Bubble Pop features a unique perspective on the bubble-shooter genre. Align bubbles in 3D-style grids and enjoy a high-energy soundtrack in this colorful and stylish GBA puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bust-a-move-eeurasia', 'GAMEBOYADVANCE', 'Super Bust-A-Move (E)(Eurasia)', '2002', 'Puzzle', 'Taito', '1', 'Block Puzzle', 'Tile-matching puzzle game with Bub and Bob.', 'Shoot bubbles to match colors and clear the screen.', 'A polished GBA version of the classic Bust-A-Move.', 'Super Bust-A-Move brings the legendary arcade puzzle action to your pocket. Face off against quirky characters and solve hundreds of bubble-based puzzles in this addictive handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-bust-a-move-uindependent', 'GAMEBOYADVANCE', 'Super Bust-A-Move (U)(Independent)', '2002', 'Puzzle', 'Taito', '1', 'Block Puzzle', 'Tile-matching puzzle game with Bub and Bob.', 'Shoot bubbles to match colors and clear the screen.', 'A polished GBA version of the classic Bust-A-Move.', 'Super Bust-A-Move brings the legendary arcade puzzle action to your pocket. Face off against quirky characters and solve hundreds of bubble-based puzzles in this addictive handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-chinese-1-and-2-advance-jcaravan', 'GAMEBOYADVANCE', 'Super Chinese 1 and 2 Advance (J)(Caravan)', '2004', 'Action', 'Culture Brain', '2', 'Beat ''em Up', 'Compilation of classic action-RPGs from the NES era.', 'Defeat enemies and explore the world in two classic hits.', 'Two legendary Super Chinese games in one GBA pack.', 'Super Chinese 1 & 2 Advance brings the "Ninja Boy" classics to the handheld. Experience a unique blend of top-down exploration and 2D beat ''em up combat in this polished Japanese collection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-collapse-ii-uindependent', 'GAMEBOYADVANCE', 'Super Collapse II (U)(Independent)', '2004', 'Puzzle', 'GameHouse', '1', 'Casual Puzzle', 'Fast-paced block-clearing puzzle game.', 'Click groups of three or more blocks to clear the board.', 'Addictive and speedy block-breaking puzzle action.', 'Super Collapse II is the perfect game for short bursts of play. Master four different game modes and test your reflexes as the blocks stack up faster and faster on your GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-dodge-ball-advance-ecezar', 'GAMEBOYADVANCE', 'Super Dodge Ball Advance (E)(Cezar)', '2001', 'Sports', 'Million', '4', 'Arcade Sports', 'Over-the-top dodgeball sports simulation.', 'Knock out the opposing team using powerful "Super Throws."', 'Fast-paced and flashy dodgeball action for GBA.', 'Super Dodge Ball Advance revives the Kunio-kun classic. Build your team, master special moves like the "Blaster Throw," and compete in a worldwide tournament in this high-energy sports game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-dodge-ball-advance-umode7', 'GAMEBOYADVANCE', 'Super Dodge Ball Advance (U)(Mode7)', '2001', 'Sports', 'Million', '4', 'Arcade Sports', 'Over-the-top dodgeball sports simulation.', 'Knock out the opposing team using powerful "Super Throws."', 'Fast-paced and flashy dodgeball action for GBA.', 'Super Dodge Ball Advance revives the Kunio-kun classic. Build your team, master special moves like the "Blaster Throw," and compete in a worldwide tournament in this high-energy sports game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-donkey-kong-jrising-sun', 'GAMEBOYADVANCE', 'Super Donkey Kong (J)(Rising Sun)', '1994', 'Platformer', 'Nintendo', '2', 'Platform Action', '2D side-scrolling platformer with pre-rendered 3D graphics.', 'Help Donkey and Diddy recover their stolen banana hoard.', 'The legendary SNES platformer on GBA.', 'Super Donkey Kong (Donkey Kong Country) brings the Kongs'' first epic adventure to handheld. Navigate through jungle, caves, and underwater levels in this faithful and challenging port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-donkey-kong-2-jcaravan', 'GAMEBOYADVANCE', 'Super Donkey Kong 2 (J)(Caravan)', '1995', 'Platformer', 'Nintendo', '2', 'Platform Action', '2D side-scrolling platformer with team-switching mechanics.', 'Rescue Donkey Kong from the clutches of Kaptain K. Rool.', 'A massive and refined platforming sequel.', 'Super Donkey Kong 2 (Diddy''s Kong Quest) is often cited as one of the best platformers ever. Master Diddy and Dixie''s unique moves to conquer Crocodile Isle in this incredible GBA version.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-donkey-kong-3-jsupplex', 'GAMEBOYADVANCE', 'Super Donkey Kong 3 (J)(sUppLeX)', '1996', 'Platformer', 'Nintendo', '2', 'Platform Action', '2D side-scrolling platformer with exploration focus.', 'Explore the Northern Kremispher and find the missing Kongs.', 'The final entry in the original DKC trilogy.', 'Super Donkey Kong 3 (Dixie Kong''s Double Trouble) features a huge world map and clever environmental puzzles. Join Dixie and Kiddy Kong in this vibrant and content-packed handheld adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-dropzone-evenom', 'GAMEBOYADVANCE', 'Super Dropzone (E)(Venom)', '2001', 'Shooter', 'Pixel', '1', 'Fixed Shooter', 'Side-scrolling defender-style arcade shooter.', 'Protect your bases from alien invaders and survive the onslaught.', 'Fast-paced and retro-style aerial combat.', 'Super Dropzone is a modern take on the classic arcade shooter formula. Fly at high speeds, deploy smart bombs, and blast through waves of enemies in this intense and colorful GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-dropzone-utrashman', 'GAMEBOYADVANCE', 'Super Dropzone (U)(TrashMan)', '2001', 'Shooter', 'Pixel', '1', 'Fixed Shooter', 'Side-scrolling defender-style arcade shooter.', 'Protect your bases from alien invaders and survive the onslaught.', 'Fast-paced and retro-style aerial combat.', 'Super Dropzone is a modern take on the classic arcade shooter formula. Fly at high speeds, deploy smart bombs, and blast through waves of enemies in this intense and colorful GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-duper-sumos-urising-sun', 'GAMEBOYADVANCE', 'Super Duper Sumos (U)(Rising Sun)', '2003', 'Action', 'Tate Interactive', '4', 'Wrestling Action', '2D beat ''em up based on the animated series.', 'Defeat the Bad Inc. forces using sumo-sized moves.', 'Quirky and humorous sumo-themed action.', 'Super Duper Sumos features the three massive heroes in a classic side-scrolling brawler. Use "Sumo-sized" special attacks and out-eat your enemies in this funny and unique GBA game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-ghouls-n-ghosts-umode7', 'GAMEBOYADVANCE', 'Super Ghouls N Ghosts (U)(Mode7)', '2002', 'Action', 'Capcom', '2', 'Platform Action', '2D side-scrolling action platformer with high difficulty.', 'Rescue the Princess from the Demon World as Sir Arthur.', 'A hardcore classic remake for the GBA.', 'Super Ghouls ''N Ghosts features the legendary challenging gameplay of the original. This GBA version adds an exclusive "Arrange Mode" with new levels and branching paths for veterans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-advance---snes-color-restoration', 'GAMEBOYADVANCE', 'Super Mario Advance - SNES Color Restoration', '2003', 'Platformer', 'Hack', '2', 'Platform Hack', '2D side-scrolling platformer with restored visuals.', 'Save Princess Peach with the original SNES color palette.', 'A visual restoration hack of Super Mario Advance.', 'Super Mario Advance - SNES Color Restoration fixes the "washed out" colors of the original GBA release. Experience the vibrant and rich aesthetic of the 16-bit classic on your handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-advance-2---instrument-restoration', 'GAMEBOYADVANCE', 'Super Mario Advance 2 - Instrument Restoration', '2002', 'Platformer', 'Hack', '2', 'Platform Hack', '2D side-scrolling platformer with improved audio.', 'Experience Super Mario World with high-fidelity SNES music.', 'An audio restoration hack for SMA2.', 'Super Mario Advance 2 - Instrument Restoration replaces the compressed GBA sounds with the high-quality samples from the SNES. Listen to Yoshi''s Island and Bowser''s Castle as they were meant to be.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-advance-4:-super-mario-bros-3-usagbpsnes-palette-hack', 'GAMEBOYADVANCE', 'Super Mario Advance 4: Super Mario Bros. 3 (USA)(GBP/SNES Palette Hack)', '2003', 'Platformer', 'Hack', '2', 'Platform Hack', '2D side-scrolling platformer with visual improvements.', 'Play the definitive version of Super Mario Bros. 3 on GBA.', 'A palette restoration hack for the SMA4 edition.', 'This hack restores the original SNES/Super Mario All-Stars color palette to SMA4. Enjoy the best version of Mario 3 with beautiful, rich colors that pop on the GBA screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-advance-color-restoration', 'GAMEBOYADVANCE', 'Super Mario Advance Color Restoration', '2003', 'Platformer', 'Hack', '2', 'Platform Hack', '2D side-scrolling platformer with restored visuals.', 'Experience the GBA Mario series with authentic 16-bit colors.', 'A comprehensive color restoration for the SMA series.', 'Super Mario Advance Color Restoration fixes the brightness issues common in early GBA titles. It returns the game to its intended artistic look, making the sprites and backgrounds more detailed.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-dx-unl', 'GAMEBOYADVANCE', 'Super Mario DX (Unl)', '2002', 'Platformer', 'Unlicensed', '2', 'Platform Action', '2D side-scrolling platformer (Unlicensed).', 'Navigate through Mario-style levels in this rare bootleg.', 'A unique and curious unlicensed Mario title.', 'Super Mario DX is an unofficial GBA game that attempts to replicate the classic Mario feel. It’s a fascinating piece of software history for fans of bootlegs and rare handheld titles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-over-knuckles-the-echidna', 'GAMEBOYADVANCE', 'Super Mario Over Knuckles The Echidna', '2004', 'Platformer', 'Hack', '2', 'Crossover Platformer', '2D arena brawler with character swaps.', 'Play as Mario within the Sonic Battle engine.', 'A creative RomHack swapping Knuckles for Mario.', 'Super Mario Over Knuckles takes the Mario cast into the intense world of Sonic Battle. Experience Mario''s moves in an isometric arena fighter with custom sprites and animations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mariomon', 'GAMEBOYADVANCE', 'Super MarioMon', '2004', 'RPG', 'Hack', '1', 'Monster RPG', 'Creature-collection RPG with Mario-themed characters.', 'Catch and train Mario characters in a Pokémon-style world.', 'A creative Mario-themed RomHack of Pokémon.', 'Super MarioMon is a fun crossover that replaces Pokémon with characters from the Mushroom Kingdom. Battle through gyms and evolve your favorite Mario friends in this RPG hybrid.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-metroid---gba-edition-40', 'GAMEBOYADVANCE', 'Super Metroid - GBA Edition 4.0', '2003', 'Action Adventure', 'Hack', '1', 'Exploration Action', '2D side-scrolling Metroidvania exploration.', 'Explore planet Zebes as Samus in this GBA fan-adaptation.', 'A fan-made port of Super Metroid for the GBA.', 'Super Metroid - GBA Edition 4.0 brings the SNES masterpiece to the handheld. Explore the non-linear world, collect power-ups, and defeat Mother Brain in this impressive technical feat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-metroid---revamp-20', 'GAMEBOYADVANCE', 'Super Metroid - Revamp 2.0', '2004', 'Action Adventure', 'Hack', '1', 'Exploration Action', '2D side-scrolling Metroidvania with modern refinements.', 'Experience a modernized and polished version of Super Metroid.', 'An enhanced and "revamped" Super Metroid experience.', 'Super Metroid - Revamp 2.0 improves the controls, physics, and world design of the original. It’s a fresh way to play the classic, designed for players who want a smoother gameplay loop.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-metroid---revamp-20-italian-translation', 'GAMEBOYADVANCE', 'Super Metroid - Revamp 2.0 Italian translation', '2004', 'Action Adventure', 'Hack', '1', 'Exploration Action', '2D side-scrolling Metroidvania with modern refinements.', 'Experience the revamped Super Metroid in Italian.', 'Italian translation of the Revamp 2.0 hack.', 'This version of Super Metroid - Revamp 2.0 offers a complete Italian translation. Experience all the gameplay improvements and the deep sci-fi story in a localized format.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-monkey-ball-jr-uvenom', 'GAMEBOYADVANCE', 'Super Monkey Ball Jr (U)(Venom)', '2002', 'Platformer', 'Amusement Vision', '1', 'Platform Action', '3D skill-based puzzle and platforming.', 'Roll your monkey to the goal within the time limit.', 'An incredibly impressive 3D technical achievement.', 'Super Monkey Ball Jr. is one of the most impressive games on GBA. Using a custom engine to replicate 3D, it features 60 challenging levels and fun mini-games that feel perfect on the handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-monkey-ball-jr-epatience', 'GAMEBOYADVANCE', 'Super Monkey Ball Jr. (E)(Patience)', '2002', 'Platformer', 'Amusement Vision', '1', 'Platform Action', '3D skill-based puzzle and platforming.', 'Roll your monkey to the goal within the time limit.', 'An incredibly impressive 3D technical achievement.', 'Super Monkey Ball Jr. is one of the most impressive games on GBA. Using a custom engine to replicate 3D, it features 60 challenging levels and fun mini-games that feel perfect on the handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-puzzle-bobble-advance-jnobody', 'GAMEBOYADVANCE', 'Super Puzzle Bobble Advance (J)(Nobody)', '2001', 'Puzzle', 'Taito', '1', 'Block Puzzle', 'Tile-matching puzzle game with Bub and Bob.', 'Shoot bubbles to match colors and clear the screen.', 'A polished GBA version of the classic Bust-A-Move.', 'Super Puzzle Bobble Advance is the Japanese edition of the hit series. Enjoy the cute aesthetic, challenging puzzles, and intense head-to-head competition that made the franchise a legend.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-puzzle-fighter-ii-emugs', 'GAMEBOYADVANCE', 'Super Puzzle Fighter II (E)(Mugs)', '2003', 'Fighting', 'Capcom', '2', '2D Fighting', 'Competitive tile-matching puzzle with Street Fighter characters.', 'Defeat your opponent by matching gems and causing "crashes."', 'The ultimate crossover competitive puzzle game.', 'Super Puzzle Fighter II (Turbo) features chibi-style versions of Ryu, Ken, and Morrigan. It’s a deep and strategic puzzle game where planning your gem drops is key to a crushing victory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-puzzle-fighter-ii-uindependent', 'GAMEBOYADVANCE', 'Super Puzzle Fighter II (U)(Independent)', '2003', 'Fighting', 'Capcom', '2', '2D Fighting', 'Competitive tile-matching puzzle with Street Fighter characters.', 'Defeat your opponent by matching gems and causing "crashes."', 'The ultimate crossover competitive puzzle game.', 'Super Puzzle Fighter II (Turbo) features chibi-style versions of Ryu, Ken, and Morrigan. It’s a deep and strategic puzzle game where planning your gem drops is key to a crushing victory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-real-mahjong-dousoukai-jcaravan', 'GAMEBOYADVANCE', 'Super Real Mahjong Dousoukai (J)(Caravan)', '2001', 'Adult / Mahjong', 'Success', '1', 'Mahjong', 'Traditional Japanese Mahjong with visual novel elements.', 'Win Mahjong hands to unlock story scenes with classmates.', 'Classic Mahjong with a charming anime aesthetic.', 'Super Real Mahjong Dousoukai brings the popular arcade series to GBA. Test your tiles skills against various opponents in this polished Japanese title featuring high-quality character art.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-robot-taisen---original-generation-eindependent', 'GAMEBOYADVANCE', 'Super Robot Taisen - Original Generation (E)(Independent)', '2002', 'Strategy RPG', 'Banpresto', '1', 'Tactical RPG', 'Tactical turn-based RPG with giant mecha combat.', 'Lead your pilot squad through strategic grid-based battles.', 'Epic mecha strategy and deep storytelling.', 'Super Robot Taisen: Original Generation is a masterpiece of strategy. Customize your mechs, upgrade pilots, and enjoy spectacular battle animations in this legendary GBA tactical RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-robot-taisen---original-generation-ujam-project', 'GAMEBOYADVANCE', 'Super Robot Taisen - Original Generation (U)(Jam Project)', '2002', 'Strategy RPG', 'Banpresto', '1', 'Tactical RPG', 'Tactical turn-based RPG with giant mecha combat.', 'Lead your pilot squad through strategic grid-based battles.', 'Epic mecha strategy and deep storytelling.', 'Super Robot Taisen: Original Generation is a masterpiece of strategy. Customize your mechs, upgrade pilots, and enjoy spectacular battle animations in this legendary GBA tactical RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-robot-taisen---original-generation-2-uindependent', 'GAMEBOYADVANCE', 'Super Robot Taisen - Original Generation 2 (U)(Independent)', '2005', 'Strategy RPG', 'Banpresto', '1', 'Tactical RPG', 'Tactical turn-based RPG with giant mecha combat.', 'Save Earth from an alien invasion with upgraded mechs.', 'The refined and challenging sequel to a strategy icon.', 'Super Robot Taisen: Original Generation 2 improves every aspect of the first game. Featuring a deeper plot and more complex tactical options, it''s a must-play for fans of the genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-robot-taisen-a-ctitan', 'GAMEBOYADVANCE', 'Super Robot Taisen A (C)(Titan)', '2001', 'Strategy RPG', 'Banpresto', '1', 'Tactical RPG', 'Tactical turn-based RPG with iconic anime crossovers.', 'Deploy legendary mechs to defeat various galactic threats.', 'Crossover mecha strategy featuring classic series.', 'Super Robot Taisen A is the first GBA entry. It features a massive roster of famous robots from Gundam, Mazinger, and more, blending their stories into one epic tactical campaign.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-robot-taisen-a-jeurasia', 'GAMEBOYADVANCE', 'Super Robot Taisen A (J)(Eurasia)', '2001', 'Strategy RPG', 'Banpresto', '1', 'Tactical RPG', 'Tactical turn-based RPG with iconic anime crossovers.', 'Deploy legendary mechs to defeat various galactic threats.', 'Crossover mecha strategy featuring classic series.', 'Super Robot Taisen A is the first GBA entry. It features a massive roster of famous robots from Gundam, Mazinger, and more, blending their stories into one epic tactical campaign.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-robot-taisen-d-jindependent', 'GAMEBOYADVANCE', 'Super Robot Taisen D (J)(Independent)', '2003', 'Strategy RPG', 'Banpresto', '1', 'Tactical RPG', 'Tactical turn-based RPG with destiny-based mechanics.', 'Fight through a post-apocalyptic world with your mech fleet.', 'Darker and more strategic entry in the SRT series.', 'Super Robot Taisen D (Destiny) introduces the "Combo" system and a branching narrative. Explore a unique story featuring mechs from Zeta Gundam and Big O in this deep GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-robot-taisen-j-jwrg', 'GAMEBOYADVANCE', 'Super Robot Taisen J (J)(WRG)', '2005', 'Strategy RPG', 'Banpresto', '1', 'Tactical RPG', 'Tactical turn-based RPG with high-quality animations.', 'Prevent a cosmic war using advanced robotic units.', 'The most visually impressive GBA Super Robot game.', 'Super Robot Taisen J (Judgment) features some of the best sprites and animations on the system. With a great cast from Full Metal Panic and G Gundam, it''s a pinnacle of the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-robot-taisen-original-generation-jeurasia', 'GAMEBOYADVANCE', 'Super Robot Taisen Original Generation (J)(Eurasia)', '2002', 'Strategy RPG', 'Banpresto', '1', 'Tactical RPG', 'Tactical turn-based RPG with giant mecha combat.', 'Lead your pilot squad through strategic grid-based battles.', 'Epic mecha strategy and deep storytelling.', 'Super Robot Taisen: Original Generation (Japanese version) set the standard for mecha strategy. Experience the origin of the "OG" saga with its intense tactical gameplay and pilot growth systems.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-robot-taisen-r-jeurasia', 'GAMEBOYADVANCE', 'Super Robot Taisen R (J)(Eurasia)', '2002', 'Strategy RPG', 'Banpresto', '1', 'Tactical RPG', 'Tactical turn-based RPG with time-travel elements.', 'Change the course of history through tactical mech warfare.', 'A classic strategic RPG featuring time-travel themes.', 'Super Robot Taisen R (Reversal) challenges players to influence the timeline. Manage your resources and deploy your best units in this strategic GBA crossover event.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-robot-wars-original-generation-2-jindependent', 'GAMEBOYADVANCE', 'Super Robot Wars Original Generation 2 (J)(Independent)', '2005', 'Strategy RPG', 'Banpresto', '1', 'Tactical RPG', 'Tactical turn-based RPG with giant mecha combat.', 'Save Earth from an alien invasion with upgraded mechs.', 'The refined and challenging sequel to a strategy icon.', 'Super Robot Wars Original Generation 2 (Japanese version) is a technical marvel. Featuring high-speed battles and a complex upgrade system, it remains a favorite for hardcore strategy fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-scourge-over-emerl-spanish', 'GAMEBOYADVANCE', 'Super Scourge Over Emerl ''[Spanish]''', '2003', 'Action', 'Hack', '1', 'Action Hack', '2D arena brawler with custom character forms.', 'Dominate the arena as the powerful Super Scourge.', 'A fast-paced combat mod in Spanish for Sonic Battle.', 'Super Scourge Over Emerl brings the anti-hero from the comics to the GBA. Featuring custom moves and Spanish text, it offers a fresh take on the classic Sonic Battle mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-shadic-over-shadow', 'GAMEBOYADVANCE', 'Super Shadic Over Shadow', '2003', 'Action', 'Hack', '1', 'Action Hack', '2D arena brawler with legendary fusion characters.', 'Defeat all rivals using the Shadic (Sonic + Shadow) fusion.', 'An intense brawler mod featuring the ultimate fusion.', 'Super Shadic Over Shadow introduces one of the most powerful fan-favorite fusions to the ring. Experience unique animations and massive power in this custom Sonic Battle modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-silver-20-over-cream', 'GAMEBOYADVANCE', 'Super Silver 2.0 Over Cream', '2003', 'Action', 'Hack', '1', 'Action Hack', '2D arena brawler with flying and psychic combat.', 'Use Super Silver''s powers to clear the battle arena.', 'A creative mod swapping Cream for Super Silver.', 'Super Silver 2.0 Over Cream transforms the combat experience with telekinetic moves and high-speed flight. Master a new fighting style in this polished GBA character mod.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-sonic-in-sonic-battle', 'GAMEBOYADVANCE', 'Super Sonic in Sonic Battle', '2003', 'Action', 'Hack', '1', 'Action Hack', '2D arena brawler with enhanced golden transformation.', 'Win the tournament with the true power of Super Sonic.', 'A high-performance Super Sonic mod for Sonic Battle.', 'This mod provides a more balanced and visually consistent Super Sonic. Enjoy increased speed and exclusive Chaos-based attacks in this essential upgrade for the brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-sonicexe-in-sonic-battle', 'GAMEBOYADVANCE', 'Super Sonic.EXE in Sonic Battle', '2003', 'Action', 'Hack', '1', 'Action Hack', '2D arena brawler with horror-themed combat.', 'Terrify your opponents as the corrupted Sonic.EXE.', 'A dark and powerful horror mod for Sonic Battle.', 'Super Sonic.EXE brings the creepypasta legend to life. Featuring spooky sprites and devastating, "unfair" power levels, it’s a unique and edgy twist on the GBA fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-street-fighter-ii-turbo-revival-ehigh-society', 'GAMEBOYADVANCE', 'Super Street Fighter II Turbo Revival (E)(High Society)', '2001', 'Fighting', 'Capcom', '2', '2D Fighting', '2D fighting game with refined sprites and new stages.', 'Fight through the World Warrior tournament to defeat Bison.', 'The definitive portable Street Fighter II experience.', 'Super Street Fighter II Turbo Revival features new character art and improved backgrounds. It remains one of the best ports on GBA, offering precise controls and arcade-perfect gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-street-fighter-ii-turbo-revival-unobody', 'GAMEBOYADVANCE', 'Super Street Fighter II Turbo Revival (U)(Nobody)', '2001', 'Fighting', 'Capcom', '2', '2D Fighting', '2D fighting game with refined sprites and new stages.', 'Fight through the World Warrior tournament to defeat Bison.', 'The definitive portable Street Fighter II experience.', 'Super Street Fighter II Turbo Revival features new character art and improved backgrounds. It remains one of the best ports on GBA, offering precise controls and arcade-perfect gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-street-fighter-ii-x-revival-jeurasia', 'GAMEBOYADVANCE', 'Super Street Fighter II X Revival (J)(Eurasia)', '2001', 'Fighting', 'Capcom', '2', '2D Fighting', '2D fighting game with refined sprites and new stages.', 'Fight through the World Warrior tournament to defeat Bison.', 'The definitive portable Street Fighter II experience.', 'Super Street Fighter II X Revival is the Japanese version of this fighting masterpiece. Master the "Turbo" speed and unleash Super Combos in this legendary handheld fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('superman---countdown-to-apokolips-epatience', 'GAMEBOYADVANCE', 'Superman - Countdown to Apokolips (E)(Patience)', '2002', 'Action Adventure', 'Titus', '1', 'Superhero Action', '3D-style action-adventure with isometric exploration.', 'Stop Darkseid and his minions from invading Metropolis.', 'A grand Superman adventure featuring iconic DC villains.', 'Superman: Countdown to Apokolips features varied missions and flying segments. Use heat vision and super-strength to protect the city in this ambitious comic-book adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('superman---countdown-to-apokolips-ueurasia', 'GAMEBOYADVANCE', 'Superman - Countdown to Apokolips (U)(Eurasia)', '2002', 'Action Adventure', 'Titus', '1', 'Superhero Action', '3D-style action-adventure with isometric exploration.', 'Stop Darkseid and his minions from invading Metropolis.', 'A grand Superman adventure featuring iconic DC villains.', 'Superman: Countdown to Apokolips features varied missions and flying segments. Use heat vision and super-strength to protect the city in this ambitious comic-book adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('superman-returns---fortress-of-solitude-urising-sun', 'GAMEBOYADVANCE', 'Superman Returns - Fortress of Solitude (U)(Rising Sun)', '2006', 'Action Adventure', 'EA Tiburon', '1', 'Superhero Action', 'Puzzle-solving action based on the Man of Steel''s home.', 'Solve the mysteries of the Fortress of Solitude.', 'A unique logic-based Superman puzzle adventure.', 'Superman Returns: Fortress of Solitude moves away from combat to focus on Kryptonian puzzles. Use your powers to interact with the fortress and unlock the story in this interesting handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('supersmashbros-pack-2020', 'GAMEBOYADVANCE', 'SuperSmashBros pack 2020', '2020', 'Fighting', 'Hack', '4', 'Crossover Fighting', 'Compilation of multi-character arena brawlers.', 'Fight with a massive roster of various iconic characters.', 'A diverse 2020 brawler pack for GBA fans.', 'Super Smash Bros Pack 2020 is a fan-curated collection of GBA fighting games and mods. Experience different arena combat styles and rosters in this value-packed handheld compilation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('surfs-up-esir-vg', 'GAMEBOYADVANCE', 'Surf''s Up (E)(Sir VG)', '2007', 'Sports', 'GameTek', '1', 'Surfing', 'Surfing simulation with tricks and racing based on the movie.', 'Ride the waves and win the Penguin World Surfing Championship.', 'Fun and tropical surfing action for all ages.', 'Surf''s Up brings the excitement of the film to your GBA. Perform big-air tricks, grind waves, and race against other penguins in this colorful and fast-paced sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('surfs-up-esupplex', 'GAMEBOYADVANCE', 'Surf''s Up (E)(sUppLeX)', '2007', 'Sports', 'GameTek', '1', 'Surfing', 'Surfing simulation with tricks and racing based on the movie.', 'Ride the waves and win the Penguin World Surfing Championship.', 'Fun and tropical surfing action for all ages.', 'Surf''s Up brings the excitement of the film to your GBA. Perform big-air tricks, grind waves, and race against other penguins in this colorful and flashy sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('surfs-up-uomgba', 'GAMEBOYADVANCE', 'Surf''s Up (U)(OMGba)', '2007', 'Sports', 'GameTek', '1', 'Surfing', 'Surfing simulation with tricks and racing based on the movie.', 'Ride the waves and win the Penguin World Surfing Championship.', 'Fun and tropical surfing action for all ages.', 'Surf''s Up brings the excitement of the film to your GBA. Perform big-air tricks, grind waves, and race against other penguins in this colorful and flashy sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('suta-komi---star-communicator-jeurasia', 'GAMEBOYADVANCE', 'Suta Komi - Star Communicator (J)(Eurasia)', '2001', 'Adventure', 'Human Entertainment', '1', 'Narrative Adventure', 'Visual novel and social simulation with an idol theme.', 'Manage and communicate with rising stars to reach fame.', 'Deep and stylish Japanese idol management sim.', 'Suta Komi (Star Communicator) focuses on relationship building and management. Guide your stars through the entertainment industry in this charming and text-heavy GBA adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sutekina-obentou-jlightforce', 'GAMEBOYADVANCE', 'Sutekina Obentou (J)(LightForce)', '2001', 'Puzzle', 'Jupiter', '1', 'Cooking Puzzle', 'Cooking simulation and puzzle game focusing on Bento boxes.', 'Create the perfect Bento box to satisfy your customers.', 'Adorable and creative Japanese cooking puzzle.', 'Sutekina Obentou is a hidden gem for fans of simulation games. Arrange food artistically and follow recipes to become a master of the Japanese lunchbox on your GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sweet-cookie-pie-jindependent', 'GAMEBOYADVANCE', 'Sweet Cookie Pie (J)(Independent)', '2001', 'Puzzle', 'Global A', '1', 'Casual Puzzle', 'Puzzle-adventure with a baking and social theme.', 'Bake delicious pies and interact with town residents.', 'Sweet and colorful Japanese puzzle-sim.', 'Sweet Cookie Pie combines logic puzzles with a sweet narrative. Solve baking challenges and unlock new recipes in this aesthetically pleasing Japanese-exclusive title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sword-of-mana-eindependent', 'GAMEBOYADVANCE', 'Sword of Mana (E)(Independent)', '2003', 'Action RPG', 'Square Enix', '1', 'Action RPG', 'Action-RPG remake of the classic Final Fantasy Adventure.', 'Protect the Mana Tree and save the world from the empire.', 'Beautifully crafted remake of the Mana series origins.', 'Sword of Mana features stunning 2D graphics and a deep class system. Experience the emotional story and fluid real-time combat that the series is famous for on the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sword-of-mana-europe-esit', 'GAMEBOYADVANCE', 'Sword of Mana (Europe) (Es,It)', '2003', 'Action RPG', 'Square Enix', '1', 'Action RPG', 'Action-RPG remake of the classic Final Fantasy Adventure.', 'Protect the Mana Tree and save the world from the empire.', 'Multi-language European version of the Mana RPG.', 'Sword of Mana (Es/It) provides the full epic experience localized for Spanish and Italian players. Explore a vibrant world and master the "Gemma" system in this high-quality JRPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sword-of-mana-europe-frde', 'GAMEBOYADVANCE', 'Sword of Mana (Europe) (Fr,De)', '2003', 'Action RPG', 'Square Enix', '1', 'Action RPG', 'Action-RPG remake of the classic Final Fantasy Adventure.', 'Protect the Mana Tree and save the world from the empire.', 'Multi-language European version of the Mana RPG.', 'Sword of Mana (Fr/De) brings this action-RPG classic to French and German audiences. Featuring polished 2D sprites and a moving soundtrack, it''s a definitive GBA adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sword-of-mana-umode7', 'GAMEBOYADVANCE', 'Sword of Mana (U)(Mode7)', '2003', 'Action RPG', 'Square Enix', '1', 'Action RPG', 'Action-RPG remake of the classic Final Fantasy Adventure.', 'Protect the Mana Tree and save the world from the empire.', 'Beautifully crafted remake of the Mana series origins.', 'Sword of Mana features stunning 2D graphics and a deep class system. Experience the emotional story and fluid real-time combat that the series is famous for on the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sylvania-family---fashion-designer-ninaritai!-jcaravan', 'GAMEBOYADVANCE', 'Sylvania Family - Fashion Designer Ninaritai! (J)(Caravan)', '2004', 'Simulation', 'Caravan', '1', 'Fashion Design', 'Life simulation and fashion design with animal characters.', 'Design outfits and help the Sylvanian characters look their best.', 'Charming fashion and creativity game for GBA.', 'Sylvania Family: Fashion Designer lets you express your style. Use a variety of fabrics and patterns to create the ultimate wardrobe for your favorite forest friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sylvania-family-4-jmugs', 'GAMEBOYADVANCE', 'Sylvania Family 4 (J)(Mugs)', '2003', 'Simulation', 'Mugs', '1', 'Life Simulation', 'Life simulation and exploration with the Sylvanian Families.', 'Explore the forest and complete tasks for your neighbors.', 'The fourth cozy installment of the Sylvanian series.', 'Sylvania Family 4 offers a peaceful and relaxing experience. Interact with adorable characters, decorate your home, and enjoy the slow-paced life of the Sylvanian world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tactics-ogre---the-knight-of-lodis-umode7', 'GAMEBOYADVANCE', 'Tactics Ogre - The Knight of Lodis (U)(Mode7)', '2002', 'Strategy RPG', 'Quest', '1', 'Tactical RPG', 'Tactical turn-based RPG with grid-based movement and deep story.', 'Lead Alphonse through a war-torn land to uncover a dark conspiracy.', 'One of the deepest strategy RPGs on the GBA.', 'Tactics Ogre: The Knight of Lodis is a masterclass in tactical JRPGs. Featuring complex branching paths, multiple endings, and a deep class system, it offers a mature and strategic experience for handheld fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tactics-ogre-gaiden---the-knight-of-lodis-jeurasia', 'GAMEBOYADVANCE', 'Tactics Ogre Gaiden - The Knight of Lodis (J)(Eurasia)', '2002', 'Strategy RPG', 'Quest', '1', 'Tactical RPG', 'Tactical turn-based RPG with grid-based movement and deep story.', 'Lead Alphonse through a war-torn land to uncover a dark conspiracy.', 'One of the deepest strategy RPGs on the GBA.', 'Tactics Ogre Gaiden: The Knight of Lodis (Japanese version) features the original tactical mechanics and lore. Experience the origin of this epic quest with its refined AI and extensive character customization.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('taiketsu-ultra-hero-jeurasia', 'GAMEBOYADVANCE', 'Taiketsu Ultra Hero (J)(Eurasia)', '2003', 'Action', 'Bandai', '1', 'Hero Action', '2D fighting game featuring Ultraman and classic monsters.', 'Win the tournament as your favorite Ultra Hero or Kaiju.', 'Intense giant-hero fighting action.', 'Taiketsu! Ultra Hero brings the iconic Tokusatsu characters to GBA. Master signature beams and melee attacks in fast-paced battles across famous Japanese cityscapes in this polished fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tak---the-great-juju-challenge-erising-sun', 'GAMEBOYADVANCE', 'Tak - The Great Juju Challenge (E)(Rising Sun)', '2003', 'Action Adventure', 'Avalanche Software', '1', 'Platform Adventure', '2D action-platformer with tag-team character mechanics.', 'Win the Juju Challenge tournament through teamwork and skill.', 'Fun and cooperative-style platforming adventure.', 'Tak: The Great Juju Challenge features Tak and Lok working together. Switch between characters to solve puzzles and use unique powers in this vibrant tribal-themed adventure for GBA.');
