INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tak-2---the-staff-of-dreams-eendless-piracy', 'GAMEBOYADVANCE', 'Tak 2 - The Staff of Dreams (E)(Endless Piracy)', '2004', 'Action Adventure', 'Avalanche Software', '1', 'Platform Adventure', 'Side-scrolling action platformer with magic and dream themes.', 'Save the Dream World using the powerful Staff of Dreams.', 'Magical action-adventure with creative puzzle elements.', 'Tak 2: The Staff of Dreams expands the Juju universe with new animal transformations and spells. Battle through surreal dreamscapes to defeat the Tlaloc in this polished GBA sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tak-2---the-staff-of-dreams-uvenom', 'GAMEBOYADVANCE', 'Tak 2 - The Staff of Dreams (U)(Venom)', '2004', 'Action Adventure', 'Avalanche Software', '1', 'Platform Adventure', 'Side-scrolling action platformer with magic and dream themes.', 'Save the Dream World using the powerful Staff of Dreams.', 'Magical action-adventure with creative puzzle elements.', 'Tak 2: The Staff of Dreams expands the Juju universe with new animal transformations and spells. Battle through surreal dreamscapes to defeat the Tlaloc in this polished GBA sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tak-and-the-power-of-juju-eindependent', 'GAMEBOYADVANCE', 'Tak and the Power of JuJu (E)(Independent)', '2002', 'Action Adventure', 'Avalanche Software', '1', 'Platform Adventure', 'Side-scrolling action-adventure with tribal magic.', 'Recover the moonstones and save the village from Tlaloc.', 'A colorful and quirky tribal platforming adventure.', 'Tak and the Power of Juju introduces players to a world of spirits and shamans. Use "Juju" powers and interact with jungle animals to solve puzzles in this charming handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tak-and-the-power-of-juju-erising-sun', 'GAMEBOYADVANCE', 'Tak And The Power Of JuJu (E)(Rising Sun)', '2002', 'Action Adventure', 'Avalanche Software', '1', 'Platform Adventure', 'Side-scrolling action-adventure with tribal magic.', 'Recover the moonstones and save the village from Tlaloc.', 'A colorful and quirky tribal platforming adventure.', 'Tak and the Power of Juju introduces players to a world of spirits and shamans. Use "Juju" powers and interact with jungle animals to solve puzzles in this charming handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tak-and-the-power-of-juju-uhyperion', 'GAMEBOYADVANCE', 'Tak And The Power of JuJu (U)(Hyperion)', '2002', 'Action Adventure', 'Avalanche Software', '1', 'Platform Adventure', 'Side-scrolling action-adventure with tribal magic.', 'Recover the moonstones and save the village from Tlaloc.', 'A colorful and quirky tribal platforming adventure.', 'Tak and the Power of Juju introduces players to a world of spirits and shamans. Use "Juju" powers and interact with jungle animals to solve puzzles in this charming handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tales-of-phantasia-ewrg', 'GAMEBOYADVANCE', 'Tales of Phantasia (E)(WRG)', '2006', 'JRPG', 'Namco', '1', 'Traditional JRPG', 'Classic JRPG with real-time "Linear Motion" battle system.', 'Travel through time to defeat the sorcerer Dhaos.', 'A legendary RPG masterpiece ported to GBA.', 'Tales of Phantasia brings the epic SNES classic to the handheld. Experience a deep, emotional story, beautiful 2D art, and the unique real-time combat that started the famous "Tales" franchise.');
