INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tales-of-the-world---narikiri-dungeon-2-jeurasia', 'GAMEBOYADVANCE', 'Tales of the World - Narikiri Dungeon 2 (J)(Eurasia)', '2002', 'Action RPG', 'Namco', '1', 'Action JRPG', 'Action-RPG with costume-based class changes.', 'Rescue your friends by exploring dungeons and changing roles.', 'Creative costume-based JRPG from the Tales series.', 'Tales of the World: Narikiri Dungeon 2 features a unique "Narikiri" system where outfits grant new skills. Enjoy dungeon crawling with cameos from various Tales of Phantasia characters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tales-of-the-world---narikiri-dungeon-3-jindependent', 'GAMEBOYADVANCE', 'Tales of the World - Narikiri Dungeon 3 (J)(Independent)', '2003', 'Action RPG', 'Namco', '1', 'Action JRPG', 'Action-RPG featuring massive Tales series crossovers.', 'Stop the dimensional threat with a team of legendary heroes.', 'The ultimate Tales crossover RPG on GBA.', 'Tales of the World: Narikiri Dungeon 3 brings together characters from Phantasia, Destiny, and Eternia. Master the tactical combat and explore branching paths in this content-rich Japanese RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tales-of-the-world---summoners-lineage-jcezar', 'GAMEBOYADVANCE', 'Tales of the World - Summoner''s Lineage (J)(Cezar)', '2003', 'Action RPG', 'Namco', '1', 'Action JRPG', 'Tactical grid-based JRPG with summoning mechanics.', 'Lead Fraine and her summons to restore peace to the land.', 'A strategic turn-based spin-off of the Tales series.', 'Tales of the World: Summoner''s Lineage focuses on tactical unit management. Summon powerful spirits and plan your moves carefully in this deep and challenging strategy title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tang-tang-ecezar', 'GAMEBOYADVANCE', 'Tang Tang (E)(Cezar)', '2002', 'Puzzle', 'Magic Pockets', '1', 'Physics Puzzle', '2D arcade puzzle-platformer with block mechanics.', 'Clear all enemies by using your hammer to move blocks.', 'Addictive arcade action similar to Solomon''s Key.', 'Tang Tang is a colorful and challenging puzzle game. Use strategy and quick reflexes to manipulate the environment and trap enemies in over 100 increasingly difficult levels.');
