INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tantei-gakuen-q---kyukyoku-trick-ni-idome-jrising-sun', 'GAMEBOYADVANCE', 'Tantei Gakuen Q - Kyukyoku Trick ni Idome (J)(Rising Sun)', '2003', 'Adventure', 'Konami', '1', 'Detective Adventure', 'Mystery-solving visual novel with logic puzzles.', 'Use your detective skills to solve "impossible" tricks.', 'Intense Japanese detective adventure based on the anime.', 'Tantei Gakuen Q (Detective School Q) features branching dialogues and logic tests. Follow Kyuu and his classmates as they solve complex murder mysteries in this polished GBA title.');
