INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tantei-jinguuji-saburou-shiroi-kage-no-syoujyo-jindependent', 'GAMEBOYADVANCE', 'Tantei Jinguuji Saburou Shiroi Kage no Syoujyo (J)(Independent)', '2004', 'Adventure', 'WorkJam', '1', 'Narrative Adventure', 'Hardboiled detective visual novel/adventure.', 'Solve the mystery of the "White Shadow" in this noir story.', 'Atmospheric and mature Japanese detective quest.', 'Tantei Jinguuji Saburou (Jake Hunter) brings noir mystery to the GBA. Investigate crime scenes and interrogate suspects in this stylish and text-heavy adventure game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('taxi-3-fpatience', 'GAMEBOYADVANCE', 'Taxi 3 (F)(Patience)', '2004', 'Racing', 'Ubisoft', '1', 'Arcade Racing', 'Arcade racing based on the French movie franchise.', 'Complete high-speed taxi deliveries and outrun the law.', 'Fast-paced urban driving action with stunts.', 'Taxi 3 on GBA features mission-based racing through the streets of Marseille. Use nitro, perform jumps, and customize your taxi in this high-speed movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('teen-titans-utrashman', 'GAMEBOYADVANCE', 'Teen Titans (U)(Trashman)', '2005', 'Action', 'TOSE', '1', 'Superhero Action', 'Side-scrolling beat ''em up with character-switching.', 'Defeat Slade and the hive of villains across Jump City.', 'Action-packed hero combat based on the hit show.', 'Teen Titans on GBA lets you play as Robin, Starfire, Beast Boy, Raven, and Cyborg. Switch between heroes on the fly to use their unique powers in this vibrant superhero brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('teen-titans-2---the-brotherhoods-revenge-urising-sun', 'GAMEBOYADVANCE', 'Teen Titans 2 - The Brotherhood''s Revenge (U)(Rising Sun)', '2006', 'Action', 'TOSE', '1', 'Superhero Action', 'Side-scrolling beat ''em up and platformer.', 'Stop the Brotherhood of Evil and save your captured teammates.', 'Dynamic superhero action sequel for GBA.', 'Teen Titans 2: The Brotherhood''s Revenge features refined combat and more character-specific puzzles. Master the team''s combined strength to overcome various challenges and bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('teenage-mutant-ninja-turtles---double-pack-usir-vg', 'GAMEBOYADVANCE', 'Teenage Mutant Ninja Turtles - Double Pack (U)(Sir VG)', '2003', 'Action', 'KONAMI', '1', 'Action Compilation', 'Compilation featuring two TMNT action games.', 'Fight through the streets of NYC in two epic adventures.', 'Value-packed double dose of Turtle power.', 'Teenage Mutant Ninja Turtles Double Pack includes the first two GBA titles. Experience classic beat ''em up action and vehicular stages in this essential handheld collection.');
