INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tg-rally-eindependent', 'GAMEBOYADVANCE', 'TG Rally (E)(Independent)', '2003', 'Racing', 'Tantalus Interactive', '2', 'Rally Racing', 'Top-down arcade rally racing with diverse tracks.', 'Beat the clock and your rivals on challenging off-road circuits.', 'Fast-paced and mud-splattered rally action.', 'TG Rally features tight controls and a variety of environments. Drift through dirt, snow, and rain to prove you are the best rally driver on the Game Boy Advance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('thats-so-raven-urising-sun', 'GAMEBOYADVANCE', 'That''s So Raven (U)(Rising Sun)', '2004', 'Action', 'Powerhead Games', '1', 'TV Show Platformer', 'Mini-game collection and adventure based on the TV show.', 'Help Raven navigate high school life and her psychic visions.', 'Fun and fashionable adventure for Raven fans.', 'That''s So Raven features a variety of fashion-based mini-games and platforming challenges. Experience the humor and style of the Disney Channel hit in this engaging handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-amazing-virtual-sea-monkeys-utrashman', 'GAMEBOYADVANCE', 'The Amazing Virtual Sea Monkeys (U)(Trashman)', '2005', 'Simulation', 'Creature Labs', '1', 'Virtual Pet', 'Virtual pet simulation with aquatic creatures.', 'Hatch, feed, and train your Sea Monkeys in a digital tank.', 'Quirky and nostalgic aquatic pet management.', 'The Amazing Virtual Sea Monkeys lets you build an underwater kingdom. Keep your pets happy and healthy while unlocking fun decorations and mini-games in this unique sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-ant-bully-ewrg', 'GAMEBOYADVANCE', 'The Ant Bully (E)(WRG)', '2006', 'Action', 'Vicarious Visions', '1', 'Action Platformer', '2D action platformer with ant-sized mechanics.', 'Defend the colony and survive the dangers of the human world.', 'Epic small-scale adventure based on the movie.', 'The Ant Bully features unique perspective gameplay. Use ant-like strength and teamwork to overcome massive obstacles and save your friends in this detailed GBA adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-ant-bully-urising-sun', 'GAMEBOYADVANCE', 'The Ant Bully (U)(Rising Sun)', '2006', 'Action', 'Vicarious Visions', '1', 'Action Platformer', '2D action platformer with ant-sized mechanics.', 'Defend the colony and survive the dangers of the human world.', 'Epic small-scale adventure based on the movie.', 'The Ant Bully features unique perspective gameplay. Use ant-like strength and teamwork to overcome massive obstacles and save your friends in this detailed GBA adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-barbie-diaries---high-school-mystery-esir-vg', 'GAMEBOYADVANCE', 'The Barbie Diaries - High School Mystery (E)(Sir VG)', '2006', 'Adventure', 'WayForward Technologies', '1', 'Mystery Adventure', 'Mystery-adventure with logic puzzles and exploration.', 'Solve the high school mystery using Barbie''s detective skills.', 'Engaging mystery and lifestyle sim starring Barbie.', 'The Barbie Diaries: High School Mystery features a compelling story and fun mini-games. Explore the school, gather clues, and help Barbie solve the case in this polished GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-barbie-diaries---high-school-mystery-urising-sun', 'GAMEBOYADVANCE', 'The Barbie Diaries - High School Mystery (U)(Rising Sun)', '2006', 'Adventure', 'WayForward Technologies', '1', 'Mystery Adventure', 'Mystery-adventure with logic puzzles and exploration.', 'Solve the mystery of the high school using Barbie''s detective skills.', 'Engaging mystery and lifestyle sim starring Barbie.', 'The Barbie Diaries: High School Mystery features a compelling story and fun mini-games. Explore the school, gather clues, and help Barbie solve the case in this polished GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-bee-game-usir-vg', 'GAMEBOYADVANCE', 'The Bee Game (U)(Sir VG)', '2005', 'Action', 'Amazing Game Company', '1', 'Action Arcade', '2D adventure featuring flight and honey collection.', 'Help the bees build their hive and protect the flowers.', 'Sweet and accessible adventure for younger players.', 'The Bee Game offers colorful graphics and simple controls. Explore vibrant gardens, collect nectar, and learn about the secret life of bees in this charming handheld game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-berenstain-bears-and-the-spooky-old-tree-utrashman', 'GAMEBOYADVANCE', 'The Berenstain Bears and the Spooky Old Tree (U)(Trashman)', '2002', 'Adventure', 'Surreal Software', '1', 'Storybook Adventure', '2D side-scrolling platformer with spooky themes.', 'Explore the spooky old tree and find the hidden treasures.', 'Friendly and atmospheric adventure for kids.', 'The Berenstain Bears and the Spooky Old Tree brings the classic book to life. Navigate through mild "spooky" levels and help the Bear family in this faithful GBA adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-bible-game-utrashman', 'GAMEBOYADVANCE', 'The Bible Game (U)(TrashMan)', '2005', 'Trivia', 'Saturn Nine Games', '1', 'Quiz Game', 'Trivia and mini-game collection based on biblical stories.', 'Compete in a game show format and answer Bible questions.', 'Educational and family-friendly trivia game.', 'The Bible Game features a variety of challenges based on well-known stories. Perfect for family play, it combines educational content with fun, arcade-style mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-cat-in-the-hat-utrashman', 'GAMEBOYADVANCE', 'The Cat in the Hat (U)(TrashMan)', '2003', 'Action', 'Maginon', '1', 'Platformer', '2D side-scrolling platformer with wacky mechanics.', 'Help the Cat in the Hat clean up the mess and find the fish.', 'Wacky and colorful platforming based on the movie.', 'The Cat in the Hat on GBA features imaginative level designs and fun gadgets. Use the Cat''s unique abilities to navigate through a world of Dr. Seuss-inspired chaos.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-cheetah-girls-urising-sun', 'GAMEBOYADVANCE', 'The Cheetah Girls (U)(Rising Sun)', '2003', 'Music', 'MGM Interactive', '1', 'Rhythm Game', 'Music-based adventure with fashion and rhythm games.', 'Help the Cheetah Girls reach stardom and win the competition.', 'Fashionable and rhythmic adventure for Disney fans.', 'The Cheetah Girls features catchy tunes and trendy mini-games. Explore New York City, practice your dance moves, and help the group achieve their musical dreams on GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-chronicles-of-narnia---the-lion-the-witch-and-the-wardrobe-urising-sun', 'GAMEBOYADVANCE', 'The Chronicles of Narnia - The Lion, The Witch and The Wardrobe (U)(Rising Sun)', '2005', 'Action', 'Griptonite Games', '1', 'Adventure Action', 'Action-RPG with exploration and character-switching.', 'Defeat the White Witch and restore peace to Narnia.', 'Epic fantasy adventure based on the classic film.', 'The Chronicles of Narnia features a deep story and tactical combat. Control the four Pevensie siblings, each with unique skills, to liberate Narnia in this polished handheld RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-fairly-odd-parents---clash-with-the-anti-world-utrashman', 'GAMEBOYADVANCE', 'The Fairly Odd Parents - Clash With The Anti-World (U)(Trashman)', '2004', 'Platformer', 'Action Forms', '1', 'Cartoon Platformer', '2D action platformer with magic-based puzzles.', 'Travel to the Anti-World and stop the anti-fairies.', 'Magical and funny adventure with Timmy Turner.', 'Clash With The Anti-World features Timmy, Cosmo, and Wanda in a bizarre parallel dimension. Use magical wishes to solve puzzles and defeat evil doppelgängers in this GBA hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-fairly-oddparents---breakin-da-rules-ueurasia', 'GAMEBOYADVANCE', 'The Fairly OddParents - Breakin'' Da Rules (U)(Eurasia)', '2003', 'Platformer', 'Blitz Games', '1', 'Cartoon Platformer', '2D action-adventure with wish-based mechanics.', 'Find the missing pages of the "Da Rules" book.', 'A wacky wish-granting adventure for GBA.', 'Breakin'' Da Rules lets you use Cosmo and Wanda''s magic to navigate through Timmy''s hometown. Solve environmental puzzles and face off against Vicky in this faithful cartoon adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-fairly-oddparents---enter-the-cleft-umode7', 'GAMEBOYADVANCE', 'The Fairly OddParents - Enter The Cleft (U)(Mode7)', '2002', 'Platformer', 'Helixe', '1', 'Cartoon Platformer', 'Side-scrolling beat ''em up and platformer.', 'Battle through comic-book worlds as the hero Cleft.', 'Action-packed superhero parody for Timmy Turner fans.', 'Enter The Cleft features Timmy''s alter-ego in a series of comic-themed levels. Use superhero powers and "wish" abilities to stop the Crimson Chin''s rivals in this fast-paced game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-fairly-oddparents---shadow-showdown-esir-vg', 'GAMEBOYADVANCE', 'The Fairly Oddparents - Shadow Showdown (E)(Sir VG)', '2004', 'Action Adventure', 'Blitz Games', '1', 'Cartoon Action', '2D platformer with puzzle and adventure elements.', 'Solve the mystery of the missing shadow and stop the darkness.', 'A high-quality magical quest with the Fairly OddParents.', 'Shadow Showdown features Timmy Turner in a quest to restore light to Dimmsdale. Use creative wishes to bypass obstacles and discover the secret behind the shadow invasion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-fairly-oddparents---shadow-showdown-grising-sun', 'GAMEBOYADVANCE', 'The Fairly OddParents - Shadow Showdown (G)(Rising Sun)', '2004', 'Action Adventure', 'Blitz Games', '1', 'Cartoon Action', '2D platformer with puzzle and adventure elements.', 'Solve the mystery of the missing shadow and stop the darkness.', 'A high-quality magical quest with the Fairly OddParents.', 'Shadow Showdown features Timmy Turner in a quest to restore light to Dimmsdale. Use creative wishes to bypass obstacles and discover the secret behind the shadow invasion.');
