INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-hobbit-emenace', 'GAMEBOYADVANCE', 'The Hobbit (E)(Menace)', '2003', 'Action Adventure', 'ICREATIVE', '1', 'Fantasy Adventure', 'Isometric action-RPG with exploration and stealth.', 'Journey to the Lonely Mountain and help reclaim the Dwarven treasure.', 'An epic and deep RPG adaptation of Tolkien''s masterpiece.', 'The Hobbit on GBA is a surprisingly deep action-RPG. Control Bilbo Baggins, solve environmental puzzles, and engage in tactical combat while exploring a beautifully rendered Middle-earth.');
