INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-invincible-iron-man-ueurasia', 'GAMEBOYADVANCE', 'The Invincible Iron Man (U)(Eurasia)', '2002', 'Action', 'Toronto Games', '1', 'Superhero Action', '2D side-scrolling run-and-gun with suit upgrades.', 'Defeat rogue AI and stop a global cyber-terrorist threat.', 'Stunningly animated comic book action for GBA.', 'The Invincible Iron Man features some of the best sprite work on the system. Fly, shoot repulsor blasts, and upgrade your armor in this fast-paced and visually impressive Marvel adventure.');
