INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-land-before-time---into-the-mysterious-beyond-utrashman', 'GAMEBOYADVANCE', 'The Land Before Time - Into the Mysterious Beyond (U)(Trashman)', '2003', 'Adventure', 'Tantalus Media', '1', 'Family Adventure', '2D platformer with character-switching and puzzles.', 'Help Littlefoot and his friends reach the Mysterious Beyond.', 'Heartwarming prehistoric adventure based on the films.', 'The Land Before Time: Into the Mysterious Beyond features teamwork-based gameplay. Use the unique skills of each dinosaur friend to bypass obstacles in this colorful platformer.');
