INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-legend-of-spyro---a-new-beginning-erising-sun', 'GAMEBOYADVANCE', 'The Legend Of Spyro - A New Beginning (E)(Rising Sun)', '2006', 'Action Adventure', 'Krome Studios', '1', 'Action Fantasy', '2D side-scrolling action adventure with breath upgrades.', 'Discover Spyro''s destiny and master the power of the four elements.', 'A cinematic and darker reboot of the Spyro saga.', 'The Legend of Spyro: A New Beginning features a focus on combat and elemental powers. Master fire, ice, earth, and electricity to defeat the Dark Master''s forces in this epic quest.');
