INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-lord-of-the-rings---the-fellowship-of-the-ring-ecezar', 'GAMEBOYADVANCE', 'The Lord of the Rings - The Fellowship of the Ring (E)(Cezar)', '2002', 'Action RPG', 'Surreal Software', '1', 'Fantasy RPG', 'Top-down action RPG with puzzle-solving.', 'Guide Frodo and the Fellowship to Rivendell and beyond.', 'A story-driven adventure based on the classic book.', 'The Lord of the Rings: The Fellowship of the Ring on GBA follows the literary journey. Explore Middle-earth, solve environmental puzzles, and engage in tactical combat in this immersive handheld RPG.');
