INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-lord-of-the-rings---the-third-age-urising-sun', 'GAMEBOYADVANCE', 'The Lord of the Rings - The Third Age (U)(Rising Sun)', '2004', 'RPG', 'Turner Broadcasting', '1', 'Fantasy RPG', 'Turn-based tactical strategy with grid movement.', 'Lead a new fellowship to defeat Sauron''s forces across Middle-earth.', 'Deep tactical strategy in the Lord of the Rings universe.', 'The Lord of the Rings: The Third Age for GBA is a high-quality strategy RPG. Manage units, upgrade hero skills, and win epic turn-based battles in this polished and challenging tactical title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-lord-of-the-rings---the-two-towers-umode7', 'GAMEBOYADVANCE', 'The Lord of the Rings - The Two Towers (U)(Mode7)', '2002', 'Action Adventure', 'Saffire', '1', 'Fantasy Action', 'Isometric hack-and-slash with multiple characters.', 'Fight through hordes of Orcs and defend the Hornburg.', 'Action-packed combat based on the blockbuster film.', 'The Lord of the Rings: The Two Towers features fluid isometric combat. Choose Aragorn, Legolas, or Gandalf, upgrade your abilities, and survive massive battles in this cinematic GBA adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-lost-vikings-eeurasia', 'GAMEBOYADVANCE', 'The Lost Vikings (E)(Eurasia)', '1993', 'Puzzle Platformer', 'Silicon & Synapse', '2', 'Classic Puzzle Platformer', 'Puzzle-platformer featuring character switching.', 'Use the unique skills of three Vikings to reach the exit.', 'A classic and clever puzzle-solving adventure.', 'The Lost Vikings brings Blizzard''s masterpiece to GBA. Switch between Erik, Olaf, and Baleog to combine their abilities and solve increasingly complex levels in this witty and challenging port.');
