INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-sims---bustin-out-umode7', 'GAMEBOYADVANCE', 'The Sims - Bustin Out (U)(Mode7)', '2003', 'Simulation', 'Maxis', '1', 'Life Simulation', 'Isometric life-simulation RPG with quest-based progression.', 'Complete missions, build a career, and move into bigger houses.', 'A deep and quirky story-driven Sims adventure.', 'The Sims: Bustin'' Out for GBA is a unique RPG experience. Unlike the PC version, you control your Sim directly to complete wacky missions, earn Simoleons, and socialise with the colorful residents of SimValley.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-sims-jrising-sun', 'GAMEBOYADVANCE', 'The Sims (J)(Rising Sun)', '2000', 'Simulation', 'Maxis', '1', 'Life Simulation', 'Isometric life-simulation RPG with quest-based progression.', 'Complete missions, build a career, and move into bigger houses.', 'A deep and quirky story-driven Sims adventure.', 'The Sims (GBA) focuses on direct control and exploration. Master mini-games to earn money, upgrade your home, and uncover the many secrets hidden in this portable Sims classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-sims-2---pets-elightforce', 'GAMEBOYADVANCE', 'The Sims 2 - Pets (E)(Lightforce)', '2006', 'Simulation', 'Maxis', '1', 'Life Simulation', 'Life-simulation focusing on pet care and career building.', 'Train your pets, manage your Sim''s life, and solve town mysteries.', 'A charming animal-centric life simulator for GBA.', 'The Sims 2: Pets lets you create the perfect animal companion. Train your pets to perform tricks, take them to work, and explore Barkingburg in this engaging and portable life sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-sims-2---pets-urising-sun', 'GAMEBOYADVANCE', 'The Sims 2 - Pets (U)(Rising Sun)', '2006', 'Simulation', 'Maxis', '1', 'Life Simulation', 'Life-simulation focusing on pet care and career building.', 'Train your pets, manage your Sim''s life, and solve town mysteries.', 'A charming animal-centric life simulator for GBA.', 'The Sims 2: Pets lets you create the perfect animal companion. Train your pets to perform tricks, take them to work, and explore Barkingburg in this engaging and portable life sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-sims-2-utrashman', 'GAMEBOYADVANCE', 'The Sims 2 (U)(Trashman)', '2005', 'Simulation', 'Maxis', '1', 'Life Simulation', 'Reality-TV style life simulation RPG.', 'Boost your show''s ratings by completing tasks and helping neighbors.', 'A unique "Strangererville" style Sims adventure.', 'The Sims 2 on GBA takes place in a TV show setting. Manage your hunger and hygiene while filming episodes, solving local mysteries, and dealing with alien invasions in this highly-rated RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-spongebob-squarepants-movie-erising-sun', 'GAMEBOYADVANCE', 'The SpongeBob SquarePants Movie (E)(Rising Sun)', '2004', 'Platformer', 'Heavy Iron Studios', '1', 'Cartoon Platformer', 'Side-scrolling action platformer with vehicle segments.', 'Travel to Shell City to recover King Neptune''s crown.', 'Epic underwater platforming based on the movie.', 'The SpongeBob SquarePants Movie game features fast-paced platforming and Patty Wagon driving levels. Use "manly" upgrades to defeat Plankton''s minions and save Bikini Bottom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-spongebob-squarepants-movie-utrashman', 'GAMEBOYADVANCE', 'The SpongeBob SquarePants Movie (U)(TrashMan)', '2004', 'Platformer', 'Heavy Iron Studios', '1', 'Cartoon Platformer', 'Side-scrolling action platformer with vehicle segments.', 'Travel to Shell City to recover King Neptune''s crown.', 'Epic underwater platforming based on the movie.', 'The SpongeBob SquarePants Movie game features fast-paced platforming and Patty Wagon driving levels. Use "manly" upgrades to defeat Plankton''s minions and save Bikini Bottom.');
