INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-sum-of-all-fears-emenace', 'GAMEBOYADVANCE', 'The Sum of All Fears (E)(Menace)', '2002', 'Shooter', 'Red Storm Entertainment', '1', 'Tactical Shooter', 'Tactical top-down shooter with squad management.', 'Neutralize terrorist threats through stealth and precision.', 'Realistic and strategic modern warfare for GBA.', 'The Sum of All Fears features tactical squad-based combat. Plan your approach, use high-tech equipment, and eliminate hostiles in this intense Tom Clancy-inspired handheld thriller.');
