INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('the-tower-sp-jcaravan', 'GAMEBOYADVANCE', 'The Tower SP (J)(Caravan)', '2005', 'Simulation', 'Opus', '1', 'City Management', 'Skyscraper management and building simulation.', 'Build and manage a 5-star skyscraper with diverse tenants.', 'The definitive portable version of SimTower.', 'The Tower SP (SimTower) challenges you to manage elevators, offices, and condos. Keep your residents happy and reach the top of the skyline in this deep and addictive management sim.');
