INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tim-burtons-the-nightmare-before-christmas---the-pumpkin-king-usupplex', 'GAMEBOYADVANCE', 'Tim Burton''s The Nightmare Before Christmas - The Pumpkin King (U)(Supplex)', '2005', 'Action Platformer', 'TOSE', '1', 'Dark Fantasy Action', '2D Metroidvania action platformer with gorgeous sprites.', 'Stop Oogie Boogie from taking over Christmas Town.', 'A stunning dark fantasy adventure by WayForward.', 'The Nightmare Before Christmas: The Pumpkin King serves as a prequel to the movie. Explore vast levels, unlock new weapons, and enjoy some of the best 2D art on the GBA.');
