INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tom-and-jerry---infurnal-escape-epatience', 'GAMEBOYADVANCE', 'Tom and Jerry - Infurnal Escape (E)(Patience)', '2000', 'Platformer', 'Bit Managers', '1', 'Cartoon Platformer', 'Side-scrolling action platformer with comedic combat.', 'Escape from hellish landscapes and outsmart your rival.', 'Wacky and colorful Tom and Jerry adventure.', 'Tom and Jerry: Infurnal Escape features classic slapstick humor. Navigate through fire and ice levels while avoiding traps and utilizing funny power-ups in this entertaining GBA title.');
