INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tom-and-jerry---the-magic-ring-erocket', 'GAMEBOYADVANCE', 'Tom and Jerry - The Magic Ring (E)(Rocket)', '2002', 'Platformer', 'Helixe', '1', 'Cartoon Platformer', '2D action platformer with varied character abilities.', 'Recover the magic ring and survive the city''s chaos.', 'Fun movie-based platforming with the iconic duo.', 'Tom and Jerry: The Magic Ring lets you play through the plot of the animated film. Solve puzzles, collect items, and enjoy the chaotic rivalry in this accessible and colorful handheld game.');
