INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tom-clancys-rainbow-six---rogue-spear-edrastic-and-lost', 'GAMEBOYADVANCE', 'Tom Clancy''s Rainbow Six - Rogue Spear (E)(Drastic and Lost)', '2002', 'Shooter', 'Red Storm Entertainment', '1', 'Tactical Shooter', 'Tactical top-down shooter with squad commands.', 'Execute precise counter-terrorist missions worldwide.', 'Deep and strategic tactical combat for GBA.', 'Rainbow Six: Rogue Spear challenges you to plan your breach. Command your squad, use realistic gadgets, and eliminate threats in this high-stakes tactical shooter adaptation.');
