INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tom-clancys-splinter-cell---pandora-tommorow-erising-sun', 'GAMEBOYADVANCE', 'Tom Clancy''s Splinter Cell - Pandora Tommorow (E)(Rising Sun)', '2005', 'Stealth Action', 'Ubisoft Shanghai', '1', 'Stealth Action', '2D side-scrolling stealth action with gadgets.', 'Stop a global biological threat as agent Sam Fisher.', 'Impressive handheld stealth-action sequel.', 'Splinter Cell: Pandora Tomorrow brings light and shadow mechanics to GBA. Use thermal goggles, silenced pistols, and acrobatic moves to infiltrate high-security enemy bases.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tom-clancys-splinter-cell---pandora-tommorow-uchameleon', 'GAMEBOYADVANCE', 'Tom Clancy''s Splinter Cell - Pandora Tommorow (U)(Chameleon)', '2005', 'Stealth Action', 'Ubisoft Shanghai', '1', 'Stealth Action', '2D side-scrolling stealth action with gadgets.', 'Stop a global biological threat as agent Sam Fisher.', 'Impressive handheld stealth-action sequel.', 'Splinter Cell: Pandora Tomorrow brings light and shadow mechanics to GBA. Use thermal goggles, silenced pistols, and acrobatic moves to infiltrate high-security enemy bases.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tom-clancys-splinter-cell-epatience', 'GAMEBOYADVANCE', 'Tom Clancy''s Splinter Cell (E)(Patience)', '2002', 'Stealth Action', 'Ubisoft Montreal', '1', 'Stealth Action', '2D side-scrolling stealth action with gadgets.', 'Infiltrate enemy territory and recover top-secret data.', 'The definitive stealth experience on the GBA.', 'Tom Clancy''s Splinter Cell captures the tension of the series in a 2D plane. Master Sam Fisher''s iconic moves, like the wall jump and split-jump, in this highly detailed action game.');
