INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tomato-adventure-english', 'GAMEBOYADVANCE', 'Tomato Adventure (English)', '2002', 'Role-Playing', 'AlphaDream', '1', 'Japanese RPG', 'Vibrant turn-based RPG with quirky gadget combat.', 'Overthrow the Gimmick King and restore the Ketchup Kingdom.', 'A colorful and creative RPG by the Mario & Luigi team.', 'Tomato Adventure is a hidden gem featuring a unique "Gimmick" battle system. Use various inventions and master timing-based attacks in this charming and translated JRPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tomato-adventure-jcezar', 'GAMEBOYADVANCE', 'Tomato Adventure (J)(Cezar)', '2002', 'Role-Playing', 'AlphaDream', '1', 'Japanese RPG', 'Vibrant turn-based RPG with quirky gadget combat.', 'Overthrow the Gimmick King and restore the Ketchup Kingdom.', 'A colorful and creative RPG by the Mario & Luigi team.', 'Tomato Adventure (Japanese version) is an essential title for RPG fans. Experience the witty writing and beautiful sprite work that would later define the AlphaDream style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tomb-raider---the-prophecy-ubatman', 'GAMEBOYADVANCE', 'Tomb Raider - The Prophecy (U)(BatMan)', '2002', 'Action Adventure', 'Core Design', '1', 'Action Adventure', 'Isometric action-adventure with platforming and puzzles.', 'Find the three magic stones to stop a cult''s dark ritual.', 'An ambitious 3D-feeling Lara Croft adventure.', 'Tomb Raider: The Prophecy features an impressive isometric engine. Navigate ancient ruins, dodge deadly traps, and engage in gunfights in this content-rich handheld journey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tonka---on-the-job-urising-sun', 'GAMEBOYADVANCE', 'Tonka - On the Job (U)(Rising Sun)', '2005', 'Simulation', 'Halestorm', '1', 'Vehicle Simulation', 'Mini-game and construction simulation for kids.', 'Complete construction jobs using various Tonka vehicles.', 'Friendly and educational construction fun.', 'Tonka: On the Job lets younger players operate bulldozers, excavators, and more. Complete various site tasks and help build the city in this creative and accessible title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tony-hawks-american-sk8land-eindependent', 'GAMEBOYADVANCE', 'Tony Hawk''s American Sk8land (E)(Independent)', '2005', 'Sports', 'Vicarious Visions', '1', 'Skateboarding', '2D skateboarding with cel-shaded graphics and tricks.', 'Rebuild a legendary skate park in Los Angeles.', 'A stylish and high-performance Tony Hawk game.', 'Tony Hawk''s American Sk8land features smooth animations and classic combo-heavy gameplay. Experience the "American Wasteland" story on GBA with a fresh and vibrant art style.');
