INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tony-hawks-pro-skater-2-fcezar', 'GAMEBOYADVANCE', 'Tony Hawk''s Pro Skater 2 (F)(Cezar)', '2000', 'Sports', 'Neversoft', '1', 'Skateboarding', 'Isometric 3D-style skateboarding with combo systems.', 'Complete skate objectives and earn high scores across pro circuits.', 'An incredible handheld port of the skating masterpiece.', 'Tony Hawk''s Pro Skater 2 on GBA is a technical achievement, offering the full console experience in an isometric view. Master manuals, grinds, and kickflips to unlock new skaters and secret areas in this definitive portable edition.');
