INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tony-hawks-pro-skater-4-urapid-fire', 'GAMEBOYADVANCE', 'Tony Hawk''s Pro Skater 4 (U)(Rapid Fire)', '2002', 'Sports', 'Neversoft', '1', 'Skateboarding', 'Isometric 3D-style skateboarding with open-ended levels.', 'Find pro skaters to take on challenges and win the championship.', 'The most expansive classic-style Tony Hawk on GBA.', 'Tony Hawk''s Pro Skater 4 removes the timer for more exploration. Master new tricks like the spine transfer and complete unique pro-skater goals in this content-rich skateboarding title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tony-hawks-underground-ueurasia', 'GAMEBOYADVANCE', 'Tony Hawk''s Underground (U)(Eurasia)', '2003', 'Sports', 'Neversoft', '1', 'Skateboarding', 'Story-driven skateboarding RPG with direct control.', 'Rise from a local skater to an underground legend.', 'A deep, plot-heavy evolution of the skating genre.', 'Tony Hawk''s Underground (THUG) adds a story mode where you create your own skater. For the first time on GBA, you can get off your board to explore levels and perform parkour-style moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tony-hawks-underground-&-kelly-slaters-pro-surfer-urising-sun', 'GAMEBOYADVANCE', 'Tony Hawk''s Underground & Kelly Slater''s Pro Surfer (U)(Rising Sun)', '2003', 'Sports', 'Neversoft', '1', 'Extreme Sports Compilation', 'Compilation featuring skating and surfing simulation.', 'Master the streets and the waves in two extreme sports hits.', 'A value-packed double dose of extreme sports.', 'This pack includes Tony Hawk''s Underground and Kelly Slater''s Pro Surfer. Switch between grinding urban rails and carving massive ocean waves in this diverse handheld collection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tony-hawks-underground-2-uvenom', 'GAMEBOYADVANCE', 'Tony Hawk''s Underground 2 (U)(Venom)', '2004', 'Sports', 'Neversoft', '1', 'Skateboarding', 'Story-driven skateboarding RPG with World Destruction Tour.', 'Join Tony Hawk and Bam Margera on a global skating rampage.', 'Chaotic and funny skating adventure for GBA.', 'Tony Hawk''s Underground 2 features even more comedy and destruction. Skate through world cities, play as wacky secret characters, and master the new "Freak Out" mechanic to boost your score.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tootuff---the-gagmachine-edeathaxe', 'GAMEBOYADVANCE', 'Tootuff - The Gagmachine (E)(DeathAxe)', '2005', 'Platformer', 'Infogrames', '1', 'Cartoon Platformer', 'Mini-game collection and adventure based on the comic.', 'Complete wacky challenges and socialise with friends.', 'Hilarious and colorful adventure starring Tootuff (Titeuf).', 'Tootuff: The Gagmachine (the English version of Titeuf) features the mischievous blond-haired kid in various school and neighborhood escapades. Enjoy a variety of witty mini-games and quirky humor.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('top-gear-gt-championship-emode7', 'GAMEBOYADVANCE', 'Top Gear GT Championship (E)(Mode7)', '2003', 'Racing', 'Infogrames', '1', 'Arcade Racing', 'Realistic circuit racing with licensed sports cars.', 'Win the GT Championship through precision driving and tuning.', 'Professional and fast-paced circuit racing for GBA.', 'Top Gear GT Championship offers deep car customization and realistic handling. Race against a field of professional drivers across international tracks in this polished racing simulation.');
