INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('top-gun---combat-zones-utrashman', 'GAMEBOYADVANCE', 'Top Gun - Combat Zones (U)(TrashMan)', '2004', 'Action', 'Bits Studios', '1', 'Aerial Combat', '3D flight simulation and aerial dogfighting.', 'Pilot advanced fighter jets and eliminate enemy targets.', 'High-octane aerial combat inspired by the film.', 'Top Gun: Combat Zones features mission-based flight action. Engage in intense dogfights, perform carrier landings, and use high-tech weaponry in this ambitious GBA flight sim.');
