INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('top-spin-2-urising-sun', 'GAMEBOYADVANCE', 'Top Spin 2 (U)(Rising Sun)', '2006', 'Sports', 'PAM Development', '1', 'Tennis Simulation', 'Professional tennis simulation with career mode.', 'Climb the world rankings and win the Grand Slam.', 'The most polished tennis experience on the GBA.', 'Top Spin 2 features realistic physics and a deep character creator. Master different playstyles and compete on various surfaces to become the world number one in this sports gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('topgear-rally-sp-jindependent', 'GAMEBOYADVANCE', 'TopGear Rally SP (J)(Independent)', '2003', 'Racing', 'Infogrames', '1', 'Rally Racing', 'Arcade rally racing with a focus on speed and drift.', 'Beat the clock and rivals in high-speed rally stages.', 'A refined and fast-paced Japanese rally racer.', 'TopGear Rally SP offers a high frame rate and tight controls. Experience the thrill of off-road racing with varied car classes and challenging track layouts on your GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('total-soccer-advance-jpolla', 'GAMEBOYADVANCE', 'Total Soccer Advance (J)(Polla)', '2003', 'Sports', 'COBRA Team', '1', 'Soccer Simulation', 'Top-down soccer simulation with arcade mechanics.', 'Lead your chosen national team to the world trophy.', 'Fast and accessible arcade-style football.', 'Total Soccer Advance focuses on quick passing and shooting. Featuring fluid animations and easy-to-learn controls, it’s a great pick for football fans looking for a portable match.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('total-soccer-manager-emenace', 'GAMEBOYADVANCE', 'Total Soccer Manager (E)(Menace)', '2002', 'Sports', 'Anco Software', '1', 'Soccer Management', 'Soccer management simulation with tactical depth.', 'Manage your team''s roster, finances, and tactics to win.', 'A deep and strategic soccer management sim for GBA.', 'Total Soccer Manager puts you in the dugout. Make crucial decisions on transfers, training, and match-day strategies to lead your club to the top of the league.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('totally-spies-2---undercover-usir-vg', 'GAMEBOYADVANCE', 'Totally Spies 2 - Undercover (U)(Sir VG)', '2005', 'Action Adventure', 'Mistic Software', '1', 'Stealth Action', '2D stealth action and gadget-based platformer.', 'Use the spies'' unique gadgets to stop global villains.', 'Stylish spy adventure based on the hit cartoon.', 'Totally Spies! 2: Undercover features Sam, Alex, and Clover in new missions. Use a variety of "Whoop" gadgets to sneak past guards and solve environmental puzzles in style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('totally-spies!-erising-sun', 'GAMEBOYADVANCE', 'Totally Spies! (E)(Rising Sun)', '2001', 'Action Adventure', 'Mistic Software', '1', 'Cartoon Action', '2D stealth action and gadget-based platformer.', 'Stop the evil mastermind and save the world from chaos.', 'Action-packed spy platforming for GBA.', 'Totally Spies! brings the energy of the animated series to the handheld. Switch between the three girls, use cool gadgets, and navigate through vibrant levels to defeat the bad guys.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('totally-spies!-urising-sun', 'GAMEBOYADVANCE', 'Totally Spies! (U)(Rising Sun)', '2001', 'Action Adventure', 'Mistic Software', '1', 'Cartoon Action', '2D stealth action and gadget-based platformer.', 'Stop the evil mastermind and save the world from chaos.', 'Action-packed spy platforming for GBA.', 'Totally Spies! brings the energy of the animated series to the handheld. Switch between the three girls, use cool gadgets, and navigate through vibrant levels to defeat the bad guys.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('totally-spies!-2---undercover-esir-vg', 'GAMEBOYADVANCE', 'Totally Spies! 2 - Undercover (E)(Sir VG)', '2005', 'Action Adventure', 'Mistic Software', '1', 'Stealth Action', '2D stealth action and gadget-based platformer.', 'Use the spies'' unique gadgets to stop global villains.', 'Stylish spy adventure based on the hit cartoon.', 'Totally Spies! 2: Undercover features Sam, Alex, and Clover in new missions. Use a variety of "Whoop" gadgets to sneak past guards and solve environmental puzzles in style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tottoko-ham-tarou-3-jindependent', 'GAMEBOYADVANCE', 'Tottoko Ham Tarou 3 (J)(Independent)', '2002', 'Simulation', 'Altron', '1', 'Life Simulation', 'Adventure and social sim with pet-raising elements.', 'Help Hamtaro and his friends solve problems in the Ham-Ham world.', 'An adorable and heart-warming Hamtaro adventure.', 'Tottoko Ham Tarou 3 features beautiful sprite work and engaging mini-games. Interact with the Ham-Ham gang, collect items, and enjoy the charming world of everyone''s favorite hamster.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tottoko-hamutaro-4---nijiiro-daikoushin-dechu-jcezar', 'GAMEBOYADVANCE', 'Tottoko Hamutaro 4 - Nijiiro Daikoushin Dechu (J)(Cezar)', '2004', 'Simulation', 'Altron', '1', 'Life Simulation', '2D platformer and adventure with rainbow themes.', 'Lead the Ham-Hams through colorful levels and find the rainbow.', 'A vibrant and cheerful Hamtaro platformer.', 'Tottoko Hamutaro 4 (Nijiiro Daikoushin) is a visually stunning Japanese exclusive. Guide the hamster parade through creative obstacles in this polished and happy GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tottoko-hamutaro-hamuhamu-sports-jcaravan', 'GAMEBOYADVANCE', 'Tottoko Hamutaro Hamuhamu Sports (J)(Caravan)', '2002', 'Sports', 'Altron', '1', 'Sports Mini-Games', 'Multi-event sports simulation featuring the Ham-Hams.', 'Win gold medals in various hamster-themed sporting events.', 'Fun and cute Olympic-style sports for GBA.', 'Hamuhamu Sports (Hamtaro: Ham-Ham Games) features archery, swimming, and racing. Compete as your favorite hamsters in this high-energy and adorable sports compilation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('touhou-kaisekiki---arabasiri', 'GAMEBOYADVANCE', 'Touhou Kaisekiki - Arabasiri', '1998', 'Shooter', 'Amusement Makers', '1', 'Bullet Hell Shooter', 'Fan-made boss rush/action game (Touhou Project).', 'Defeat the powerful maid Sakuya in this custom challenge.', 'A unique fan-made Touhou action game for GBA.', 'Touhou Kaisekiki: Arabasiri is a homebrew project that brings the bullet-hell world of Touhou to the handheld. Face off against iconic characters in this impressive technical fan creation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('touhoumon-world-link-fire-red-hack', 'GAMEBOYADVANCE', 'Touhoumon World Link (Fire Red Hack)', '2016', 'RPG', 'Fan Made', '1', 'Monster Collecting', 'Creature collection RPG (FireRed Hack).', 'Collect and train Touhou characters in a massive new world.', 'An expansive Touhou-themed Pokémon overhaul.', 'Touhoumon World Link is a legendary FireRed hack. Replace Pokémon with "Puppets" (Touhou characters), explore new regions, and experience a custom story with adjusted difficulty and unique movesets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('touhoumon-zoku-gensokyo-scenario', 'GAMEBOYADVANCE', 'Touhoumon Zoku Gensokyo Scenario', '2015', 'RPG', 'Fan Made', '1', 'Story Driven RPG', 'Creature collection RPG with visual novel elements.', 'Navigate the Gensokyo region and battle rival trainers.', 'A deep Touhou-themed RPG experience for GBA.', 'Touhoumon Zoku Gensokyo Scenario focuses on the lore of the Touhou Project. Build your team of spirits and battle through a story-heavy campaign featuring iconic locations and music.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('toukon-heat-jcezar', 'GAMEBOYADVANCE', 'Toukon Heat (J)(Cezar)', '2002', 'Sports', 'Spike', '1', 'Professional Wrestling', '2D professional wrestling with cinematic moves.', 'Win the championship belt in the New Japan Pro-Wrestling ring.', 'Intense and stylish Japanese wrestling action.', 'Toukon Heat features a unique "Heat" system for cinematic finishing moves. Play as legendary wrestlers like Antonio Inoki in this polished and fast-paced GBA grappler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('toy-robot-force-jeurasia', 'GAMEBOYADVANCE', 'Toy Robot Force (J)(Eurasia)', '2003', 'Action', 'Tamsoft', '1', 'Robot Action', 'Turn-based tactical RPG with customizable robots.', 'Build the ultimate robot team to defeat the rebel forces.', 'Strategic mecha combat with deep customization.', 'Toy Robot Force lets you collect parts and weapons to build unique battle bots. Engage in grid-based tactical battles and upgrade your mechanical squad in this Japanese gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('trick-star-eindependent', 'GAMEBOYADVANCE', 'Trick Star (E)(Independent)', '2002', 'Puzzle', 'Game Arts', '1', 'Arcade Puzzle', '3D-style stunt racing on hoverbikes.', 'Win races and perform high-scoring stunts on futuristic tracks.', 'High-speed futuristic racing with a focus on tricks.', 'Trick Star features impressive pseudo-3D graphics. Navigate loops and jumps on your hoverbike while competing against aggressive AI in this fast-paced GBA racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tringo-eindependent', 'GAMEBOYADVANCE', 'Tringo (E)(Independent)', '2003', 'Puzzle', 'Crave Entertainment', '1', 'Word Puzzle', 'Puzzle game combining Tetris and Bingo mechanics.', 'Fit falling shapes into a grid to clear lines and score points.', 'An addictive and unique hybrid puzzle experience.', 'Tringo is the perfect "pick up and play" game. Strategically place geometric blocks on a 5x5 grid to match Bingo patterns in this clever and relaxing handheld puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tringo-utrashman', 'GAMEBOYADVANCE', 'Tringo (U)(Trashman)', '2003', 'Puzzle', 'Crave Entertainment', '1', 'Word Puzzle', 'Puzzle game combining Tetris and Bingo mechanics.', 'Fit falling shapes into a grid to clear lines and score points.', 'An addictive and unique hybrid puzzle experience.', 'Tringo is the perfect "pick up and play" game. Strategically place geometric blocks on a 5x5 grid to match Bingo patterns in this clever and relaxing handheld puzzler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('trollz---hair-affair-eindependent-endeit', 'GAMEBOYADVANCE', 'Trollz - Hair Affair (E)(Independent) EN,DE,IT', '2005', 'Adventure', 'Mistic Software', '1', 'Fashion Adventure', 'Social simulation and mini-game adventure.', 'Help the Trollz girls navigate school life and magic.', 'A colorful and fashion-focused adventure for GBA.', 'Trollz: Hair Affair features the five best friends in a series of quests. Play rhythm games, design outfits, and use "Ancient Magic" to solve problems in this vibrant title.');
