INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tron-20---killer-app-ebatman', 'GAMEBOYADVANCE', 'Tron 2.0 - Killer App (E)(BatMan)', '2003', 'Action', 'Bits Studios', '1', 'Sci-Fi Action', 'Isometric action-shooter with hacking puzzles.', 'Prevent a computer virus from taking over the Grid.', 'A stunning and atmospheric cyber-adventure.', 'Tron 2.0: Killer App is one of the GBA''s best-looking games. Use your light disc, hack systems, and race light cycles in this polished extension of the Tron universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tron-20---killer-app-urising-sun', 'GAMEBOYADVANCE', 'Tron 2.0 - Killer App (U)(Rising Sun)', '2003', 'Action', 'Bits Studios', '1', 'Sci-Fi Action', 'Isometric action-shooter with hacking puzzles.', 'Prevent a computer virus from taking over the Grid.', 'A stunning and atmospheric cyber-adventure.', 'Tron 2.0: Killer App is one of the GBA''s best-looking games. Use your light disc, hack systems, and race light cycles in this polished extension of the Tron universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tsuukin-hitofude-jcaravan', 'GAMEBOYADVANCE', 'Tsuukin Hitofude (J)(Caravan)', '2003', 'Puzzle', 'Miles Laboratory', '1', 'Calligraphy Puzzle', 'Logical puzzle game featuring one-stroke drawings.', 'Clear all blocks by drawing a single continuous line.', 'A challenging and minimalist Japanese brain-teaser.', 'Tsuukin Hitofude (known as Polarium elsewhere) is a masterclass in puzzle design. Use the stylus or D-pad to flip tiles in one stroke to match colors and clear the board.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turbo-turtle-adventure-uquartex', 'GAMEBOYADVANCE', 'Turbo Turtle Adventure (U)(Quartex)', '2002', 'Platformer', 'Bit Managers', '1', 'Cartoon Platformer', 'Physics-based puzzle-platformer.', 'Guide the turtle through trap-filled levels to the exit.', 'A slow-paced and strategic puzzle adventure.', 'Turbo Turtle Adventure requires precision and patience. Tilt platforms and use environmental tools to roll your turtle safely through increasingly complex and dangerous mazes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turok-evolution-eeurasia', 'GAMEBOYADVANCE', 'Turok Evolution (E)(Eurasia)', '2002', 'Action', 'Acclaim', '1', 'FPS Action', '2D side-scrolling run-and-gun with platforming.', 'Fight through dinosaur-infested lands to stop the Sleg army.', 'Brutal and fast-paced prehistoric action.', 'Turok Evolution on GBA is a classic side-scrolling shooter. Use a massive arsenal of weapons to blast through reptilian enemies and survive intense boss fights in this action-packed title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turok-evolution-udumper', 'GAMEBOYADVANCE', 'Turok Evolution (U)(Dumper)', '2002', 'Action', 'Acclaim', '1', 'FPS Action', '2D side-scrolling run-and-gun with platforming.', 'Fight through dinosaur-infested lands to stop the Sleg army.', 'Brutal and fast-paced prehistoric action.', 'Turok Evolution on GBA is a classic side-scrolling shooter. Use a massive arsenal of weapons to blast through reptilian enemies and survive intense boss fights in this action-packed title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tweety-&-the-magic-gems-eeurasia', 'GAMEBOYADVANCE', 'Tweety & The Magic Gems (E)(Eurasia)', '2003', 'Platformer', 'Kemco', '1', 'Cartoon Platformer', 'Board-game style adventure with mini-games.', 'Collect the magic gems and reach the finish line before Sylvester.', 'A fun and competitive Looney Tunes party game.', 'Tweety & The Magic Gems plays like a digital board game. Travel across the globe, play wacky mini-games, and use power-ups to outsmart your opponents in this family-friendly title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tweety-and-the-magic-gems-gmugs', 'GAMEBOYADVANCE', 'Tweety and The Magic Gems (G)(Mugs)', '2003', 'Platformer', 'Kemco', '1', 'Cartoon Platformer', 'Board-game style adventure with mini-games.', 'Collect the magic gems and reach the finish line before Sylvester.', 'A fun and competitive Looney Tunes party game.', 'Tweety & The Magic Gems plays like a digital board game. Travel across the globe, play wacky mini-games, and use power-ups to outsmart your opponents in this family-friendly title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tweety-and-the-magic-gems-uindependent', 'GAMEBOYADVANCE', 'Tweety and The Magic Gems (U)(Independent)', '2003', 'Platformer', 'Kemco', '1', 'Cartoon Platformer', 'Board-game style adventure with mini-games.', 'Collect the magic gems and reach the finish line before Sylvester.', 'A fun and competitive Looney Tunes party game.', 'Tweety & The Magic Gems plays like a digital board game. Travel across the globe, play wacky mini-games, and use power-ups to outsmart your opponents in this family-friendly title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tweety-to-hearty-party-jcapital', 'GAMEBOYADVANCE', 'Tweety to Hearty Party (J)(Capital)', '2001', 'Party', 'Game Freak', '1', 'Mini-Game Party', 'Mini-game collection and social sim featuring Tweety.', 'Help Tweety navigate a party filled with friends and foes.', 'Cute and cheerful Japanese Tweety adventure.', 'Tweety to Hearty Party is a lighthearted collection of activities. Interact with Looney Tunes characters and complete simple, fun tasks in this charming Japanese exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('twin-series-4---hamu-hamu-monster-ex-&-f-puzzle-hamusuta-jindependent', 'GAMEBOYADVANCE', 'Twin Series 4 - Hamu Hamu Monster EX & F Puzzle Hamusuta (J)(Independent)', '2003', 'Compilation', 'D3 Publisher', '1', 'Family Mini-Games', 'Dual-game cartridge (Monster collecting + Puzzle).', 'Train monsters and solve puzzles in this 2-in-1 pack.', 'A value-packed Japanese twin-game collection.', 'This Twin Series entry features Hamu Hamu Monster EX and a Hamster-themed puzzle game. Experience two different genres on a single GBA cartridge, perfect for long trips.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('twin-series-5---wanwan-meitantei-ex-&-manou-no-kuni-no-cake-house-jindependent', 'GAMEBOYADVANCE', 'Twin Series 5 - Wanwan Meitantei EX & Manou no Kuni no Cake House (J)(Independent)', '2003', 'Compilation', 'D3 Publisher', '1', 'Family Mini-Games', 'Dual-game cartridge (Detective mystery + Cooking).', 'Solve doggy crimes and manage a magical cake shop.', 'A quirky 2-in-1 Japanese adventure pack.', 'Twin Series 5 combines the Wanwan Meitantei detective game with a cake-making simulation. Switch between solving mysteries and baking delicious treats in this unique combo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('twin-series-6---wannyan-idol-gakuen-&-koinu-to-issho-jindependent', 'GAMEBOYADVANCE', 'Twin Series 6 - Wannyan Idol Gakuen & Koinu to Issho (J)(Independent)', '2003', 'Compilation', 'D3 Publisher', '1', 'Family Mini-Games', 'Dual-game cartridge (Idol sim + Pet simulation).', 'Train to be an idol and raise a cute puppy.', 'Two popular lifestyle simulations in one pack.', 'Twin Series 6 features Wannyan Idol Gakuen and Koinu to Issho. Manage your career as a rising star while taking care of a virtual pet in this content-rich Japanese release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('twin-series-vol-1---mezase-debut!-fashion-designer-monogatari-&-kawaii-pet-game-gallery-2-jindependent', 'GAMEBOYADVANCE', 'Twin Series Vol. 1 - Mezase Debut! Fashion Designer Monogatari & Kawaii Pet Game Gallery 2 (J)(Independent)', '2002', 'Compilation', 'D3 Publisher', '1', 'Life Simulation', 'Dual-game cartridge (Fashion design + Pet gallery).', 'Create trendy outfits and play with a variety of pets.', 'The ultimate creativity and pet pack for GBA.', 'Twin Series Vol. 1 includes a fashion designer sim and a pet mini-game gallery. Express your style and bond with virtual animals in this diverse and relaxing compilation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ty-the-tasmanian-tiger-2---bush-rescue-uvenom', 'GAMEBOYADVANCE', 'Ty the Tasmanian Tiger 2 - Bush Rescue (U)(Venom)', '2004', 'Platformer', 'Krome Studios', '1', 'Action Platformer', '2D side-scrolling action platformer with combat.', 'Save the Australian Outback from the Quinkan invasion.', 'A vibrant and fast-paced boomerang adventure.', 'Ty the Tasmanian Tiger 2 features fluid combat and various boomerangs to collect. Explore the bush and use Ty''s bite and toss moves to defeat enemies in this polished platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ty-the-tasmanian-tiger-3---night-of-the-quinkan-utrashman', 'GAMEBOYADVANCE', 'Ty the Tasmanian Tiger 3 - Night of the Quinkan (U)(Trashman)', '2005', 'Platformer', 'Krome Studios', '1', 'Action Platformer', '2D side-scrolling action platformer with combat.', 'Defeat the Quinkan army and save your home.', 'The epic conclusion to the Ty trilogy on GBA.', 'Ty the Tasmanian Tiger 3 ramps up the action with "Bunyip" mech suits and new elemental boomerangs. Fight through large levels and face off against massive bosses in this great platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('uchu-no-stellvia-jrising-sun', 'GAMEBOYADVANCE', 'Uchu No Stellvia (J)(Rising Sun)', '2003', 'Sci-Fi', 'Brainstorm', '1', 'Visual Novel', 'Visual novel and space-academy simulation.', 'Train to be a pilot and build relationships with classmates.', 'A stylish anime-based sci-fi adventure.', 'Uchu No Stellvia (Stellvia of the Universe) follows the story of Shima Katase. Balance school life, pilot training, and social interactions in this high-quality Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('uchuu-daisakusen-chocovader---uchuu-kara-no-shinryakusha-jcezar', 'GAMEBOYADVANCE', 'Uchuu Daisakusen Chocovader - Uchuu kara no Shinryakusha (J)(Cezar)', '2002', 'Action', 'Creatures', '1', 'Arcade Shooter', 'Arcade shooter and mini-game collection with aliens.', 'Defend Earth from a quirky alien invasion.', 'Wacky and creative Japanese sci-fi fun.', 'Chocovader is a unique title featuring a series of fast-paced mini-games. Capture aliens and solve puzzles to prevent a humorous invasion in this aesthetically pleasing GBA game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ueki-no-housoku-shinki-sakuretsu!-nouryokumono-battle-jcaravan', 'GAMEBOYADVANCE', 'Ueki no Housoku Shinki Sakuretsu! Nouryokumono Battle (J)(Caravan)', '2004', 'Action', 'Banpresto', '1', 'Anime Fighting', '2D fighting game with unique "power" mechanics.', 'Win the tournament to become the next King of the World.', 'Intense supernatural brawler based on the anime.', 'Ueki no Housoku (The Law of Ueki) features the show''s unique combat system. Master Ueki''s ability to turn trash into trees in this fast-paced and tactical GBA fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultimate-arcade-games-utrashman', 'GAMEBOYADVANCE', 'Ultimate Arcade Games (U)(Trashman)', '2004', 'Compilation', 'Digital Eclipse', '1', 'Classic Arcade', 'Collection of classic arcade-style mini-games.', 'Master various retro challenges and achieve high scores.', 'A versatile pack of arcade classics for GBA.', 'Ultimate Arcade Games brings a variety of retro-inspired experiences to your handheld. From shooters to action puzzles, this collection offers great replay value for fans of old-school arcade mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultimate-beach-soccer-uevasion', 'GAMEBOYADVANCE', 'Ultimate Beach Soccer (U)(Evasion)', '2003', 'Sports', 'Silicon Dreams', '2', 'Beach Soccer', '4v4 beach soccer with acrobatic moves and tricks.', 'Win the beach soccer world tour on sandy pitches.', 'Fast-paced, acrobatic arcade soccer action.', 'Ultimate Beach Soccer focuses on spectacular overhead kicks and fast gameplay. Master the physics of the sand to outplay your opponents in this sunny and energetic sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultimate-brain-games-ueurasia', 'GAMEBOYADVANCE', 'Ultimate Brain Games (U)(Eurasia)', '2004', 'Educational', 'Majesco', '1', 'Brain Training', 'Strategy compilation featuring Chess, Checkers, and more.', 'Outsmart the AI in the world''s most popular board games.', 'The ultimate portable board game collection.', 'Ultimate Brain Games features deep AI and multiple difficulty levels for Chess, Backgammon, and Mahjong. It''s the perfect companion for fans of logic and strategy puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultimate-card-games-uindependent', 'GAMEBOYADVANCE', 'Ultimate Card Games (U)(Independent)', '2003', 'Card', 'GameTek', '4', 'Card Games', 'Massive collection of classic card and casino games.', 'Master dozens of card variants and win big.', 'A complete portable casino and card game suite.', 'Ultimate Card Games includes everything from Poker and Solitaire to Blackjack. With customizable rules and clean graphics, it’s the definitive card game anthology for GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultimate-muscle---the-path-of-the-superhero-uvenom', 'GAMEBOYADVANCE', 'Ultimate Muscle - The Path of the Superhero (U)(Venom)', '2003', 'Fighting', 'Aki Corporation', '1', 'Anime Wrestling', '2D wrestling brawler with over-the-top special moves.', 'Rise through the ranks to become the ultimate superhero wrestler.', 'Wild and wacky anime-style wrestling action.', 'Ultimate Muscle: The Path of the Superhero brings the hit anime to GBA. Execute devastating "Kinniku" finishers and enjoy the hilarious story mode in this high-energy fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultimate-puzzle-games-utrashman', 'GAMEBOYADVANCE', 'Ultimate Puzzle Games (U)(Trashman)', '2004', 'Puzzle', 'Digital Eclipse', '1', 'Logic Puzzle', 'Compilation of diverse logic and tile puzzles.', 'Solve hundreds of levels across various puzzle types.', 'A value-packed treasury of brain-teasers.', 'Ultimate Puzzle Games offers an endless supply of Sudoku, Crosswords, and slider puzzles. It is designed to keep your mind sharp with increasing challenges and intuitive controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultimate-spider-man-eindependent', 'GAMEBOYADVANCE', 'Ultimate Spider-Man (E)(Independent)', '2006', 'Action', 'Vicarious Visions', '1', 'Superhero Action', '2D side-scrolling action with comic-book aesthetics.', 'Play as Spider-Man or Venom to uncover a dark conspiracy.', 'Stunning comic-style action with dual-protagonists.', 'Ultimate Spider-Man features fluid web-swinging and intense combat. Switch between Peter Parker''s agility and Venom''s brute force in this visually striking handheld adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultimate-spider-man-erising-sun', 'GAMEBOYADVANCE', 'Ultimate Spider-Man (E)(Rising Sun)', '2006', 'Action', 'Vicarious Visions', '1', 'Superhero Action', '2D side-scrolling action with comic-book aesthetics.', 'Play as Spider-Man or Venom to uncover a dark conspiracy.', 'Stunning comic-style action with dual-protagonists.', 'Ultimate Spider-Man features fluid web-swinging and intense combat. Switch between Peter Parker''s agility and Venom''s brute force in this visually striking handheld adventure.');
