INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultimate-winter-games-ueurasia', 'GAMEBOYADVANCE', 'Ultimate Winter Games (U)(Eurasia)', '2004', 'Sports', 'Digital Eclipse', '4', 'Winter Sports', 'Winter sports simulation featuring multiple disciplines.', 'Win gold medals in skiing, snowboarding, and bobsledding.', 'A comprehensive and chilly sports compilation.', 'Ultimate Winter Games lets you compete in the most popular cold-weather events. Master the timing for jumps and turns to top the international leaderboards on GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultra-keibitai---monster-attack-jcaravan', 'GAMEBOYADVANCE', 'Ultra Keibitai - Monster Attack (J)(Caravan)', '2002', 'Action', 'Banpresto', '1', 'Monster Action', 'Tactical tower defense and action with giant monsters.', 'Defend the city from iconic Kaiju using specialized units.', 'Intense monster-defense strategy based on Ultraman.', 'Ultra Keibitai: Monster Attack puts you in charge of Earth''s defense. Deploy tanks and jets to stop massive monsters in this strategic Japanese-exclusive gem.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('unfabulous-urising-sun', 'GAMEBOYADVANCE', 'Unfabulous (U)(Rising Sun)', '2005', 'Adventure', 'Black Lantern Studios', '1', 'Teen Adventure', 'Adventure and social sim based on the Nickelodeon show.', 'Help Addie navigate middle school drama and music.', 'A charming social adventure for fans of the series.', 'Unfabulous features music-themed mini-games and choice-driven dialogue. Help Addie Singer balance her social life and her guitar practice in this faithful show adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('uno-52-esupplex', 'GAMEBOYADVANCE', 'Uno 52 (E)(sUppLeX)', '2004', 'Card', 'Black Lantern Studios', '4', 'Card Games', 'Traditional card game with 52 unique variations.', 'Be the first to empty your hand using classic Uno rules.', 'The world-famous card game with a digital twist.', 'Uno 52 adds a unique spin to the classic gameplay, incorporating poker-style elements and varied challenges to keep the traditional card game fresh on GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('uno-52-usir-vg', 'GAMEBOYADVANCE', 'Uno 52 (U)(Sir VG)', '2004', 'Card', 'Black Lantern Studios', '4', 'Card Games', 'Traditional card game with 52 unique variations.', 'Be the first to empty your hand using classic Uno rules.', 'The world-famous card game with a digital twist.', 'Uno 52 adds a unique spin to the classic gameplay, incorporating poker-style elements and varied challenges to keep the traditional card game fresh on GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('uno-free-fall-esir-vg', 'GAMEBOYADVANCE', 'Uno Free Fall (E)(Sir VG)', '2006', 'Puzzle', 'Black Lantern Studios', '1', 'Falling Blocks', 'Falling-block puzzle game mixed with Uno mechanics.', 'Match colors and numbers to clear the falling tiles.', 'An addictive hybrid of Uno and Tetris.', 'Uno Free Fall challenges your reflexes and strategy. Drop tiles to create matches and trigger cascades in this fast-paced puzzle evolution of the classic card game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('uno-freefall-usir-vg', 'GAMEBOYADVANCE', 'Uno Freefall (U)(Sir VG)', '2006', 'Puzzle', 'Black Lantern Studios', '1', 'Falling Blocks', 'Falling-block puzzle game mixed with Uno mechanics.', 'Match colors and numbers to clear the falling tiles.', 'An addictive hybrid of Uno and Tetris.', 'Uno Free Fall challenges your reflexes and strategy. Drop tiles to create matches and trigger cascades in this fast-paced puzzle evolution of the classic card game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('urban-yeti!-ueurasia', 'GAMEBOYADVANCE', 'Urban Yeti! (U)(Eurasia)', '2004', 'Action', 'Konami', '1', 'Action Platformer', 'Top-down action-adventure with wacky missions.', 'Help a yeti find a mate in the middle of a busy city.', 'A bizarre and hilarious GTA-style cult classic.', 'Urban Yeti! is one of the most unique GBA titles. Navigate urban environments, complete weird mini-games, and avoid the police in this humorous and chaotic adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('v-master-cross-joldskool', 'GAMEBOYADVANCE', 'V-Master Cross (J)(OldSkool)', '2003', 'RPG', 'Mitchell', '1', 'Card Battle RPG', 'Turn-based creature-battling RPG with card elements.', 'Collect powerful monsters and win the V-Master tournament.', 'A strategic and deep Japanese monster-battler.', 'V-Master Cross features a unique mechanical-monster aesthetic. Build your deck, evolve your creatures, and master tactical combat in this polished Japanese RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('v-rally-3-eparadox', 'GAMEBOYADVANCE', 'V-Rally 3 (E)(Paradox)', '2002', 'Racing', 'Eden Studios', '1', 'Rally Racing', 'Realistic rally racing with an advanced 3D engine.', 'Win the World Rally Championship across global stages.', 'Arguably the best-looking racing game on the GBA.', 'V-Rally 3 is a technical masterpiece. It features a true cockpit view, realistic car damage, and incredible 3D-style graphics that pushed the GBA hardware to its absolute limits.');
