INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('van-helsing-erising-sun', 'GAMEBOYADVANCE', 'Van Helsing (E)(Rising Sun)', '2004', 'Action', 'Saffire', '1', 'Action Adventure', 'Isometric action-adventure with monster-slaying combat.', 'Hunt down Dracula and his minions across Transylvania.', 'Dark and atmospheric monster-hunting action.', 'Van Helsing for GBA features varied weaponry like dual pistols and the tojo blade. Battle through eerie levels and solve gothic puzzles in this movie-based adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('van-helsing-uindependent', 'GAMEBOYADVANCE', 'Van Helsing (U)(Independent)', '2004', 'Action', 'Saffire', '1', 'Action Adventure', 'Isometric action-adventure with monster-slaying combat.', 'Hunt down Dracula and his minions across Transylvania.', 'Dark and atmospheric monster-hunting action.', 'Van Helsing for GBA features varied weaponry like dual pistols and the tojo blade. Battle through eerie levels and solve gothic puzzles in this movie-based adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vattroller-x-jwrg', 'GAMEBOYADVANCE', 'Vattroller X (J)(WRG)', '2002', 'Action', 'Jaleco', '1', 'Arcade Action', '2D action game featuring spinning robot combat.', 'Master the "Vattroller" mechanics to defeat rival bots.', 'Fast-paced and unique Japanese action-puzzler.', 'Vattroller X features a distinctive control scheme where spinning is the key to combat. Master the momentum to crush enemies and clear stages in this creative title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vecinos-invasores-swrg', 'GAMEBOYADVANCE', 'Vecinos Invasores (S)(WRG)', '2006', 'Platformer', 'Behaviour Interactive', '1', 'Cartoon Platformer', 'Side-scrolling action platformer based on the movie.', 'Help RJ and the gang steal food while avoiding traps.', 'Fun and stealthy adventure for all ages.', 'Vecinos Invasores (Over the Hedge) features character-switching and heist-style missions. Use the unique skills of the woodland creatures to navigate suburban backyards.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('veggietales---larryboy-and-the-bad-apple-urising-sun', 'GAMEBOYADVANCE', 'VeggieTales - LarryBoy and the Bad Apple (U)(Rising Sun)', '2003', 'Action', 'Neko Entertainment', '1', 'Stealth Action', '2D platformer with puzzle and adventure elements.', 'Stop the Bad Apple and teach the citizens of Bumblyburg.', 'A family-friendly adventure with a moral message.', 'LarryBoy and the Bad Apple features the popular VeggieTales hero. Use your "super-suction" ears to solve puzzles and defeat the Bad Apple in this colorful GBA game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vip-evenom', 'GAMEBOYADVANCE', 'VIP (E)(Venom)', '2002', 'Sports', 'Hitmaker', '2', 'Tennis Simulation', 'Side-scrolling beat ''em up based on the TV show.', 'Protect celebrities and fight off waves of enemies.', 'Stylish action-brawler featuring Pamela Anderson.', 'VIP on GBA brings the high-fashion bodyguard action to your handheld. Use martial arts and gadgets to protect your clients through various action-packed missions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('virtua-tennis-epatience', 'GAMEBOYADVANCE', 'Virtua Tennis (E)(Patience)', '2002', 'Sports', 'Hitmaker', '2', 'Tennis Simulation', 'Professional tennis simulation with arcade mechanics.', 'Rise to the top of the rankings and win the world tour.', 'A near-perfect port of the legendary arcade hit.', 'Virtua Tennis (Sega Professional Tennis) features incredibly fluid gameplay and addictive mini-games. It remains one of the most playable and precise sports games on the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('virtua-tennis-uvenom', 'GAMEBOYADVANCE', 'Virtua Tennis (U)(Venom)', '2002', 'Board', 'GameTek', '2', 'Chess Simulation', 'Professional tennis simulation with arcade mechanics.', 'Rise to the top of the rankings and win the world tour.', 'A near-perfect port of the legendary arcade hit.', 'Virtua Tennis (Sega Professional Tennis) features incredibly fluid gameplay and addictive mini-games. It remains one of the most playable and precise sports games on the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('virtual-kasparov-evenom', 'GAMEBOYADVANCE', 'Virtual Kasparov (E)(Venom)', '2002', 'Board', 'GameTek', '2', 'Chess Simulation', 'Professional Chess simulation with grandmaster AI.', 'Learn from the best and win the world chess tournament.', 'The most advanced Chess trainer on a handheld.', 'Virtual Kasparov features a deep tutorial system endorsed by Garry Kasparov. Whether you are a beginner or an expert, the adaptive AI provides a world-class challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('virtual-kasparov-unobody', 'GAMEBOYADVANCE', 'Virtual Kasparov (U)(Nobody)', '2005', 'Adventure', 'Climax Studios', '1', 'Magical Adventure', 'Professional Chess simulation with grandmaster AI.', 'Learn from the best and win the world chess tournament.', 'The most advanced Chess trainer on a handheld.', 'Virtual Kasparov features a deep tutorial system endorsed by Garry Kasparov. Whether you are a beginner or an expert, the adaptive AI provides a world-class challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('witch-erising-sun', 'GAMEBOYADVANCE', 'W.I.T.C.H. (E)(Rising Sun)', '2001', 'Boxing', 'Infogrames', '1', 'Arcade Boxing', '2D side-scrolling action platformer with magic.', 'Use the elemental powers of the five guardians to save Meridian.', 'Magical action-adventure based on the Disney comic.', 'W.I.T.C.H. on GBA lets you control Will, Irma, Taranee, Cornelia, and Hay Lin. Switch between guardians to use their unique elemental magic to solve puzzles and defeat Phobos''s minions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wade-hixtons-counter-punch-uindependent', 'GAMEBOYADVANCE', 'Wade Hixtons Counter Punch (U)(Independent)', '2001', 'Boxing', 'Infogrames', '1', 'Arcade Boxing', 'Arcade-style boxing with RPG and shop elements.', 'Rise through the ranks of the boxing world to become champ.', 'A stylish and humorous spiritual successor to Punch-Out!!', 'Wade Hixton''s Counter Punch is a cult classic. Featuring vibrant character designs and tight controls, you must learn enemy patterns and buy new moves to conquer the colorful roster of opponents.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wagamama-fairy-mirumo-de-pon---8-nin-no-toki-no-yousei-jrising-sun', 'GAMEBOYADVANCE', 'Wagamama Fairy Mirumo De Pon - 8 Nin no Toki no Yousei (J)(Rising Sun)', '2004', 'Adventure', 'Hudson Soft', '1', 'Anime Adventure', 'Adventure and social simulation with magic fairies.', 'Help the fairies restore peace to the human world.', 'Charming Japanese adventure based on the anime.', 'Wagamama Fairy Mirumo De Pon! features mini-games and a heartfelt story. Interact with Muglox fairies and help Kaede navigate her school life in this polished Japanese title.');